package com.herbrunhelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * While the bank shows the Farm run items: a small box under the Farm run button listing anything
 * the run needs that isn't in your bank. (The button itself is Romte1's FarmBankButton.)
 */
class BankSupplyOverlay extends Overlay
{
	private static final Color BORDER = new Color(20, 18, 14);
	private static final Color SHORT = new Color(255, 95, 85);

	private final HerbRunPlugin plugin;
	private final HerbRunConfig config;
	private final FarmBankButton button;

	@Inject
	BankSupplyOverlay(HerbRunPlugin plugin, HerbRunConfig config, FarmBankButton button)
	{
		this.plugin = plugin;
		this.config = config;
		this.button = button;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Rectangle anchor = button.bounds();
		if (!config.bankSupplyTab() || anchor == null || !button.isActive())
		{
			return null;
		}
		List<String> lines = new ArrayList<>();
		for (HerbRunPlugin.SupplyRow r : plugin.getSupplyRows())
		{
			int short_ = r.need - r.carried - r.inBank;
			if (short_ > 0)
			{
				lines.add(short_ + " x " + r.name);
			}
		}
		if (lines.isEmpty())
		{
			return null;
		}
		lines.add(0, "Not in your bank:");
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int lw = 0;
		for (String l : lines)
		{
			lw = Math.max(lw, fm.stringWidth(l));
		}
		int bw = lw + 12;
		int bh = lines.size() * 13 + 6;
		int bx = anchor.x + anchor.width - bw;
		int by = anchor.y + anchor.height + 3;
		g.setColor(new Color(30, 26, 22, 235));
		g.fillRoundRect(bx, by, bw, bh, 6, 6);
		g.setColor(BORDER);
		g.drawRoundRect(bx, by, bw, bh, 6, 6);
		int ly = by + 13;
		for (int i = 0; i < lines.size(); i++)
		{
			g.setColor(i == 0 ? Color.LIGHT_GRAY : SHORT);
			g.drawString(lines.get(i), bx + 6, ly);
			ly += 13;
		}
		return null;
	}
}

package com.herbrunhelper;

/**
 * Everything the runs plant: herbs, allotments, trees, fruit trees and hardwood trees.
 *
 * Constant names match the crop names in patch-states.tsv. Growth stages follow RuneLite's
 * Time Tracking plugin (Produce.java): a crop finishes after (stages - 1) growth
 * ticks of its patch type's tick length. Gardener payments are from the OSRS Wiki and can be
 * handed over noted.
 */
public enum Crop
{
	// Herbs: 20-minute ticks
	GUAM(PatchType.HERB, "Guam", 9, "Guam seed", 5, null, 0, 249),
	MARRENTILL(PatchType.HERB, "Marrentill", 14, "Marrentill seed", 5, null, 0, 251),
	TARROMIN(PatchType.HERB, "Tarromin", 19, "Tarromin seed", 5, null, 0, 253),
	HARRALANDER(PatchType.HERB, "Harralander", 26, "Harralander seed", 5, null, 0, 255),
	RANARR(PatchType.HERB, "Ranarr", 32, "Ranarr seed", 5, null, 0, 257),
	TOADFLAX(PatchType.HERB, "Toadflax", 38, "Toadflax seed", 5, null, 0, 2998),
	IRIT(PatchType.HERB, "Irit", 44, "Irit seed", 5, null, 0, 259),
	AVANTOE(PatchType.HERB, "Avantoe", 50, "Avantoe seed", 5, null, 0, 261),
	KWUARM(PatchType.HERB, "Kwuarm", 56, "Kwuarm seed", 5, null, 0, 263),
	SNAPDRAGON(PatchType.HERB, "Snapdragon", 62, "Snapdragon seed", 5, null, 0, 3000),
	HUASCA(PatchType.HERB, "Huasca", 65, "Huasca seed", 5, null, 0, 30097),
	CADANTINE(PatchType.HERB, "Cadantine", 67, "Cadantine seed", 5, null, 0, 265),
	LANTADYME(PatchType.HERB, "Lantadyme", 73, "Lantadyme seed", 5, null, 0, 2481),
	DWARF_WEED(PatchType.HERB, "Dwarf weed", 79, "Dwarf weed seed", 5, null, 0, 267),
	TORSTOL(PatchType.HERB, "Torstol", 85, "Torstol seed", 5, null, 0, 269),

	// Allotments: 10-minute ticks, 3 seeds per patch
	POTATO(PatchType.ALLOTMENT, "Potato", 1, "Potato seed", 5, "Compost", 2, 1942),
	ONION(PatchType.ALLOTMENT, "Onion", 5, "Onion seed", 5, "Potatoes(10)", 1, 1957),
	CABBAGE(PatchType.ALLOTMENT, "Cabbage", 7, "Cabbage seed", 5, "Onions(10)", 1, 1965),
	TOMATO(PatchType.ALLOTMENT, "Tomato", 12, "Tomato seed", 5, "Cabbages(10)", 2, 1982),
	SWEETCORN(PatchType.ALLOTMENT, "Sweetcorn", 20, "Sweetcorn seed", 7, "Jute fibre", 10, 5986),
	STRAWBERRY(PatchType.ALLOTMENT, "Strawberry", 31, "Strawberry seed", 7, "Apples(5)", 1, 5504),
	WATERMELON(PatchType.ALLOTMENT, "Watermelon", 47, "Watermelon seed", 9, "Curry leaf", 10, 5982),
	SNAPE_GRASS(PatchType.ALLOTMENT, "Snape grass", 61, "Snape grass seed", 8, "Jangerberries", 5, 231),

	// Trees: 40-minute ticks
	OAK(PatchType.TREE, "Oak", 15, "Oak sapling", 5, "Tomatoes(5)", 1, 1521),
	WILLOW(PatchType.TREE, "Willow", 30, "Willow sapling", 7, "Apples(5)", 1, 1519),
	MAPLE(PatchType.TREE, "Maple", 45, "Maple sapling", 9, "Oranges(5)", 1, 1517),
	YEW(PatchType.TREE, "Yew", 60, "Yew sapling", 11, "Cactus spine", 10, 1515),
	MAGIC(PatchType.TREE, "Magic", 75, "Magic sapling", 13, "Coconut", 25, 1513),

	// Fruit trees: 160-minute ticks (16 hours)
	APPLE(PatchType.FRUIT_TREE, "Apple", 27, "Apple sapling", 7, "Sweetcorn", 9, 1955),
	BANANA(PatchType.FRUIT_TREE, "Banana", 33, "Banana sapling", 7, "Apples(5)", 4, 1963),
	ORANGE(PatchType.FRUIT_TREE, "Orange", 39, "Orange sapling", 7, "Strawberries(5)", 3, 2108),
	CURRY(PatchType.FRUIT_TREE, "Curry", 42, "Curry sapling", 7, "Bananas(5)", 5, 5970),
	PINEAPPLE(PatchType.FRUIT_TREE, "Pineapple", 51, "Pineapple sapling", 7, "Watermelon", 10, 2114),
	PAPAYA(PatchType.FRUIT_TREE, "Papaya", 57, "Papaya sapling", 7, "Pineapple", 10, 5972),
	PALM(PatchType.FRUIT_TREE, "Palm", 68, "Palm sapling", 7, "Papaya fruit", 15, 5974),
	DRAGONFRUIT(PatchType.FRUIT_TREE, "Dragonfruit", 81, "Dragonfruit sapling", 7, "Coconut", 15, 22929),

	// Hardwood: 640-minute ticks
	TEAK(PatchType.HARDWOOD, "Teak", 35, "Teak sapling", 8, "Limpwurt root", 15, 6333),
	MAHOGANY(PatchType.HARDWOOD, "Mahogany", 55, "Mahogany sapling", 9, "Yanillian hops", 25, 6332),
	// Sailing update hardwoods (19 Nov 2025): stages from RuneLite's Produce, payments from the OSRS Wiki.
	CAMPHOR(PatchType.HARDWOOD, "Camphor", 66, "Camphor sapling", 9, "White berries", 10, 32904),
	IRONWOOD(PatchType.HARDWOOD, "Ironwood", 80, "Ironwood sapling", 9, "Curry leaf", 10, 32907),
	ROSEWOOD(PatchType.HARDWOOD, "Rosewood", 92, "Rosewood sapling", 10, "Dragonfruit", 8, 32910),

	// Bushes: stages and ticks from RuneLite's Produce; levels, payments from the OSRS Wiki.
	REDBERRIES(PatchType.BUSH, "Redberry", 10, "Redberry seed", 6, "Cabbages(10)", 4, 1951),
	CADAVABERRIES(PatchType.BUSH, "Cadavaberry", 22, "Cadavaberry seed", 7, "Tomatoes(5)", 3, 753),
	DWELLBERRIES(PatchType.BUSH, "Dwellberry", 36, "Dwellberry seed", 8, "Strawberries(5)", 3, 2126),
	JANGERBERRIES(PatchType.BUSH, "Jangerberry", 48, "Jangerberry seed", 9, "Watermelon", 6, 247),
	WHITEBERRIES(PatchType.BUSH, "Whiteberry", 59, "Whiteberry seed", 9, "Mushroom", 8, 239),
	POISON_IVY(PatchType.BUSH, "Poison ivy", 70, "Poison ivy seed", 9, null, 0, 6018), // immune to disease

	// Hops: 4 seeds (jute 3).
	BARLEY(PatchType.HOPS, "Barley", 3, "Barley seed", 5, "Compost", 3, 6006),
	HAMMERSTONE(PatchType.HOPS, "Hammerstone", 4, "Hammerstone seed", 5, "Marigolds", 1, 5994),
	ASGARNIAN(PatchType.HOPS, "Asgarnian", 8, "Asgarnian seed", 6, "Onions(10)", 1, 5996),
	JUTE(PatchType.HOPS, "Jute", 13, "Jute seed", 6, "Barley malt", 6, 5931),
	YANILLIAN(PatchType.HOPS, "Yanillian", 16, "Yanillian seed", 7, "Tomatoes(5)", 1, 5998),
	KRANDORIAN(PatchType.HOPS, "Krandorian", 21, "Krandorian seed", 8, "Cabbages(10)", 3, 6000),
	WILDBLOOD(PatchType.HOPS, "Wildblood", 28, "Wildblood seed", 9, "Nasturtiums", 1, 6002),

	// Cactus (potato cactus grows every 10 minutes, not 80).
	CACTUS(PatchType.CACTUS, "Cactus", 55, "Cactus seed", 8, "Cadava berries", 6, 6016),
	POTATO_CACTUS(PatchType.CACTUS, "Potato cactus", 64, "Potato cactus seed", 8, "Snape grass", 8, 3138),

	// Special trees.
	CALQUAT(PatchType.CALQUAT, "Calquat", 72, "Calquat sapling", 9, "Poison ivy berries", 8, 5980),
	SPIRIT_TREE(PatchType.SPIRIT_TREE, "Spirit tree", 83, "Spirit sapling", 13, "Monkey nuts", 5, 6063),
	CELASTRUS(PatchType.CELASTRUS, "Celastrus", 85, "Celastrus sapling", 6, "Potato cactus", 8, 22935),
	REDWOOD(PatchType.REDWOOD, "Redwood", 90, "Redwood sapling", 11, "Dragonfruit", 6, 19669);

	private final PatchType type;
	private final String displayName;
	private final int level;
	private final String seedName;
	private final int stages;
	private final String paymentItem;
	private final int paymentQuantity;
	/** Item id of the produce, used as the crop's picture (game item ids, as in RuneLite's ItemID). */
	private final int iconItemId;

	Crop(PatchType type, String displayName, int level, String seedName, int stages,
		String paymentItem, int paymentQuantity, int iconItemId)
	{
		this.iconItemId = iconItemId;
		this.type = type;
		this.displayName = displayName;
		this.level = level;
		this.seedName = seedName;
		this.stages = stages;
		this.paymentItem = paymentItem;
		this.paymentQuantity = paymentQuantity;
	}

	/** Allotments take 3 seeds, hops 4 (jute 3); everything else 1 seed or sapling. */
	public int getSeedsPerPatch()
	{
		if (type == PatchType.HOPS)
		{
			return this == JUTE ? 3 : 4;
		}
		return type == PatchType.ALLOTMENT ? 3 : 1;
	}

	/**
	 * Other things the gardener wants on top of {@link #getPaymentItem()}: name and quantity
	 * pairs. Spirit trees: 5 monkey nuts, plus 1 monkey bar and 1 ground tooth (OSRS Wiki).
	 */
	public String[][] getExtraPayments()
	{
		if (this == SPIRIT_TREE)
		{
			return new String[][]{{"Monkey bar", "1"}, {"Ground tooth", "1"}};
		}
		return new String[0][];
	}

	/** Minutes between growth ticks: the patch type's, except potato cactus (10, per RuneLite). */
	public int getTickMinutes()
	{
		return this == POTATO_CACTUS ? 10 : type.getTickMinutes();
	}

	public PatchType getType()
	{
		return type;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public int getLevel()
	{
		return level;
	}

	/** Herb seed or tree sapling name, as it appears in the bank. */
	public String getSeedName()
	{
		return seedName;
	}

	/** Growth stages including the finished one. */
	public int getStages()
	{
		return stages;
	}

	public int getGrowthMinutes()
	{
		return (stages - 1) * getTickMinutes();
	}

	public int getIconItemId()
	{
		return iconItemId;
	}

	/** Tree seed (before potting), or null for herbs. From the OSRS Wiki. */
	public String getTreeSeedName()
	{
		switch (this)
		{
			case OAK:
				return "Acorn";
			case WILLOW:
				return "Willow seed";
			case MAPLE:
				return "Maple seed";
			case YEW:
				return "Yew seed";
			case MAGIC:
				return "Magic seed";
			case APPLE:
				return "Apple tree seed";
			case BANANA:
				return "Banana tree seed";
			case ORANGE:
				return "Orange tree seed";
			case CURRY:
				return "Curry tree seed";
			case PINEAPPLE:
				return "Pineapple seed";
			case PAPAYA:
				return "Papaya tree seed";
			case PALM:
				return "Palm tree seed";
			case DRAGONFRUIT:
				return "Dragonfruit tree seed";
			case TEAK:
				return "Teak seed";
			case MAHOGANY:
				return "Mahogany seed";
			case CAMPHOR:
				return "Camphor seed";
			case IRONWOOD:
				return "Ironwood seed";
			case ROSEWOOD:
				return "Rosewood seed";
			case CALQUAT:
				return "Calquat tree seed";
			case SPIRIT_TREE:
				return "Spirit seed";
			case CELASTRUS:
				return "Celastrus seed";
			case REDWOOD:
				return "Redwood tree seed";
			default:
				return null;
		}
	}

	/** Seedling in a plant pot before watering, e.g. "Maple seedling". Null for seeds planted directly. */
	public String getSeedlingName()
	{
		if (!type.usesSaplings())
		{
			return null;
		}
		return this == SPIRIT_TREE ? "Spirit seedling" : displayName + " seedling";
	}

	/** Watered seedling, growing into a sapling, e.g. "Maple seedling (w)". Null for seeds planted directly. */
	public String getWateredSeedlingName()
	{
		String s = getSeedlingName();
		return s == null ? null : s + " (w)";
	}

	public String getPaymentItem()
	{
		return paymentItem;
	}

	public int getPaymentQuantity()
	{
		return paymentQuantity;
	}

	/** Crop by its patch-states.tsv name, or null for weeds/crops the plugin doesn't plant. */
	public static Crop fromTableName(String name)
	{
		try
		{
			return valueOf(name);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}

	/**
	 * The crop whose seed/sapling appears in a chat message like "You plant a Ranarr seed...".
	 * Picks the longest match, so "pineapple sapling" isn't read as "apple sapling".
	 */
	public static Crop fromPlantMessage(String message)
	{
		String lower = message.toLowerCase();
		if (!lower.contains("you plant"))
		{
			return null;
		}
		Crop best = null;
		for (Crop crop : values())
		{
			String seed = crop.seedName.toLowerCase();
			if (lower.contains(seed) && (best == null || seed.length() > best.seedName.length()))
			{
				best = crop;
			}
		}
		return best;
	}
}

package com.herbrunhelper;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Fairy ring tiles by code (from RuneLite's world map plugin, FairyRingLocation.java). */
final class FairyRings
{
	private static final Map<String, int[]> TILES = new HashMap<>();
	private static final Pattern RING = Pattern.compile("fairy ring ([A-D][I-L][P-S])");

	static
	{
		put("AIQ", 2995, 3112);
		put("AIR", 2699, 3249);
		put("AIS", 1430, 3323);
		put("AJP", 1648, 3011);
		put("AJR", 2779, 3615);
		put("AJS", 2499, 3898);
		put("AKP", 3283, 2704);
		put("AKQ", 2318, 3617);
		put("AKR", 1823, 3539);
		put("AKS", 2570, 2958);
		put("ALP", 2502, 3638);
		put("ALQ", 3598, 3496);
		put("ALR", 3059, 4877);
		put("ALS", 2643, 3497);
		put("BIP", 3409, 3326);
		put("BIQ", 3248, 3095);
		put("BIS", 2635, 3268);
		put("BJP", 2264, 2976);
		put("BJS", 2147, 3069);
		put("BKP", 2384, 3037);
		put("BKR", 3468, 3433);
		put("BKS", 2411, 4436);
		put("BLP", 2432, 5127);
		put("BLR", 2739, 3353);
		put("BLS", 1293, 3495);
		put("CIP", 2512, 3886);
		put("CIQ", 2527, 3129);
		put("CIR", 1303, 3762);
		put("CIS", 1636, 3869);
		put("CJQ", 3178, 2445);
		put("CJR", 2704, 3578);
		put("CKQ", 1358, 2943);
		put("CKR", 2800, 3005);
		put("CKS", 3446, 3472);
		put("CLP", 3081, 3208);
		put("CLR", 2737, 2739);
		put("CLS", 2681, 3083);
		put("DIP", 3036, 4761);
		put("DIS", 3109, 3149);
		put("DJP", 2657, 3232);
		put("DJR", 1452, 3659);
		put("DKP", 2899, 3113);
		put("DKR", 3126, 3496);
		put("DKS", 2743, 3721);
		put("DLP", 2923, 10455);
		put("DLQ", 3422, 3018);
		put("DLR", 2212, 3101);
	}

	private FairyRings()
	{
	}

	private static void put(String code, int x, int y)
	{
		TILES.put(code, new int[]{x, y});
	}

	/** True if a ring stands within a few tiles of this spot. */
	static boolean isRingAt(int x, int y)
	{
		for (int[] t : TILES.values())
		{
			if (Math.abs(t[0] - x) <= 3 && Math.abs(t[1] - y) <= 3)
			{
				return true;
			}
		}
		return false;
	}

	/** {x, y} of the ring, or null. */
	static int[] tile(String code)
	{
		return code == null ? null : TILES.get(code);
	}

	/**
	 * The ring you walk to for this step: named in the directions ("Walk to fairy ring ALQ"),
	 * or the ring you arrived at on the step before ("Back to the ring").
	 */
	static String startRing(RunPlan.RouteStep step, RunPlan.RouteStep previous)
	{
		if (step.teleport == null || step.teleport.getFairyCode() == null || step.teleportLabel == null)
		{
			return null;
		}
		Matcher m = RING.matcher(step.teleportLabel);
		if (m.find())
		{
			return m.group(1);
		}
		if (step.teleportLabel.startsWith("Back to the ring") && previous != null && previous.teleport != null)
		{
			return previous.teleport.getFairyCode();
		}
		return null;
	}
}

package com.herbrunhelper;

import java.awt.Rectangle;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ScriptEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.plugins.banktags.BankTagsService;

/**
 * The farming button in the bank title bar. It opens the "Farm run" Bank Tags view with the run's
 * items and checklist. Client-side only: nothing is sent to the server.
 *
 * By Romte1, from his pull request #1 (FarmBankButton.java), used with his permission. Changes
 * here: it opens this plugin's own run tag (RunBankTag), uses the "Animated bank button" setting
 * (bankTabGlow), and reports its bounds while open for the "Not in your bank" box.
 */
@Singleton
class FarmBankButton
{
	static final String TAG = RunBankTag.NAME;
	private static final int BUTTON_SIZE = 25;
	/** Left of Quest Helper's button (x 408), so the two sit in a row without overlapping. */
	private static final int BUTTON_X = 380;
	private static final int BUTTON_Y = 5;

	private final Client client;
	private final BankTagsService bankTagsService;
	private final HerbRunConfig config;
	private Widget background;
	private Widget icon;
	private boolean pulse;

	@Inject
	FarmBankButton(Client client, BankTagsService bankTagsService, HerbRunConfig config)
	{
		this.client = client;
		this.bankTagsService = bankTagsService;
		this.config = config;
	}

	/** Adds the button when the bank opens. */
	void init()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (bank == null || bank.isHidden())
		{
			return;
		}
		// Same geometry as Quest Helper's bank button: a 25px square with a 19px icon at +3,+3.
		background = create(bank, SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL, BUTTON_SIZE, BUTTON_X, BUTTON_Y);
		// A spade/shovel is a simple, centred farming tool. The farming skill icon has uneven
		// transparent padding and looked off-centre in the 19px square.
		icon = create(bank, SpriteID.Staticons2.SHOVEL, BUTTON_SIZE - 6, BUTTON_X + 3, BUTTON_Y + 3);
		for (Widget part : new Widget[]{background, icon})
		{
			part.setAction(1, "View Farm run");
			part.setOnOpListener((JavaScriptCallback) this::onClick);
		}
		updateSprite();
	}

	boolean isActive()
	{
		return TAG.equals(bankTagsService.getActiveTag());
	}

	/**
	 * Where the button is on screen while its tab is closed, so the attention effect can be
	 * drawn around it; null when there is nothing to point at.
	 */
	Rectangle attentionBounds()
	{
		if (isActive() || background == null || background.isHidden())
		{
			return null;
		}
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (bank == null || bank.isHidden())
		{
			return null;
		}
		Rectangle bounds = background.getBounds();
		return bounds == null || bounds.width <= 0 || bounds.height <= 0 ? null : bounds;
	}

	/** Where the button is on screen (open or closed), or null if it isn't showing. */
	Rectangle bounds()
	{
		if (background == null || background.isHidden())
		{
			return null;
		}
		Rectangle b = background.getBounds();
		return b == null || b.width <= 0 ? null : b;
	}

	/** Called each game tick to keep the pressed look in step with the bank. */
	void onGameTick()
	{
		// While the tab is closed, flash the button gently so the player notices it.
		pulse = !isActive() && config.bankTabGlow()
			&& (System.currentTimeMillis() / 800) % 2 == 0;
		updateSprite();
	}

	void destroy()
	{
		if (isActive())
		{
			bankTagsService.closeBankTag();
		}
		if (icon != null)
		{
			icon.setHidden(true);
		}
		if (background != null)
		{
			background.setHidden(true);
		}
		background = null;
		icon = null;
	}

	private void onClick(ScriptEvent event)
	{
		if (event.getOp() != 2)
		{
			return;
		}
		if (isActive())
		{
			bankTagsService.closeBankTag();
		}
		else
		{
			bankTagsService.openBankTag(TAG, BankTagsService.OPTION_NO_LAYOUT);
		}
		updateSprite();
	}

	private void updateSprite()
	{
		if (background == null)
		{
			return;
		}
		int sprite = isActive() || pulse ? SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED
			: SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL;
		if (background.getSpriteId() != sprite)
		{
			background.setSpriteId(sprite);
			background.revalidate();
		}
		String name = isActive() ? TAG + " (on)" : TAG;
		if (!name.equals(background.getName()))
		{
			background.setName(name);
			if (icon != null)
			{
				icon.setName(name);
			}
		}
	}

	private static Widget create(Widget parent, int spriteId, int size, int x, int y)
	{
		Widget widget = parent.createChild(-1, WidgetType.GRAPHIC);
		widget.setOriginalWidth(size);
		widget.setOriginalHeight(size);
		widget.setOriginalX(x);
		widget.setOriginalY(y);
		widget.setSpriteId(spriteId);
		widget.setHasListener(true);
		widget.setName(TAG);
		widget.revalidate();
		return widget;
	}
}

package com.herbrunhelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small growing-garden attention effect around the bank's Farm run button while its tab is
 * closed: a breathing green halo, a slow ring of tiny leaves and a few golden fireflies rising
 * from the button.
 *
 * By Romte1, from his pull request #1 (FarmBankButtonOverlay.java), used with his permission.
 */
class FarmBankButtonOverlay extends Overlay
{
	private static final Color LEAF = new Color(120, 230, 90);
	private static final Color GOLD = new Color(255, 215, 90);
	private static final Color SPORE = new Color(220, 255, 170);

	private final FarmBankButton button;
	private final HerbRunConfig config;

	@Inject
	FarmBankButtonOverlay(FarmBankButton button, HerbRunConfig config)
	{
		this.button = button;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.bankTabGlow())
		{
			return null;
		}
		Rectangle bounds = button.attentionBounds();
		if (bounds == null || bounds.width <= 0 || bounds.height <= 0)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		double pulse = 0.5 + 0.5 * Math.sin(now / 420.0);
		int cx = bounds.x + bounds.width / 2;
		int cy = bounds.y + bounds.height / 2;

		// Warm the button itself a little, so it visibly lights up and dims.
		int sheen = (int) (24 + 22 * pulse);
		graphics.setColor(new Color(GOLD.getRed(), GOLD.getGreen(), GOLD.getBlue(), sheen));
		graphics.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 6, 6);

		// A soft green halo that breathes around the frame.
		Stroke oldStroke = graphics.getStroke();
		graphics.setStroke(new BasicStroke(1.4f));
		for (int ring = 0; ring < 3; ring++)
		{
			int pad = 2 + ring;
			int alpha = (int) ((18 + 28 * pulse) / (ring + 1));
			graphics.setColor(new Color(LEAF.getRed(), LEAF.getGreen(), LEAF.getBlue(), alpha));
			graphics.drawRoundRect(bounds.x - pad, bounds.y - pad,
				bounds.width + pad * 2, bounds.height + pad * 2, 8, 8);
		}
		graphics.setStroke(oldStroke);

		// A slow ring of tiny leaves, alternating in brightness.
		int leaves = 8;
		for (int i = 0; i < leaves; i++)
		{
			double angle = now / 1250.0 + i * Math.PI * 2 / leaves;
			double orbit = 14 + 1.5 * pulse;
			int x = cx + (int) Math.round(Math.cos(angle) * orbit);
			int y = cy + (int) Math.round(Math.sin(angle) * orbit * 0.78);
			int alpha = (int) (90 + 90 * (0.5 + 0.5 * Math.sin(now / 260.0 + i)));
			drawLeaf(graphics, x, y, alpha);
		}

		// Fireflies rising from the bottom edge and fading out.
		for (int i = 0; i < 4; i++)
		{
			double t = ((now % 1900) / 1900.0 + i / 4.0) % 1.0;
			int x = bounds.x + 3 + (int) Math.round((bounds.width - 6) * ((i * 0.37 + 0.1) % 1.0))
				+ (int) Math.round(Math.sin(now / 260.0 + i * 2) * 2);
			int y = bounds.y + bounds.height - 1 - (int) Math.round(t * 18);
			int alpha = Math.max(0, (int) (210 * Math.sin(Math.PI * t)));
			Color colour = i % 2 == 0 ? GOLD : SPORE;
			graphics.setColor(new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), alpha));
			graphics.fillOval(x, y, 3, 3);
			graphics.setColor(new Color(255, 255, 240, Math.max(0, alpha / 2)));
			graphics.fillRect(x + 1, y + 1, 1, 1);
		}
		return null;
	}

	private static void drawLeaf(Graphics2D graphics, int x, int y, int alpha)
	{
		alpha = Math.max(0, Math.min(255, alpha));
		graphics.setColor(new Color(LEAF.getRed(), LEAF.getGreen(), LEAF.getBlue(), alpha));
		graphics.fillRect(x, y - 1, 3, 3);
		graphics.fillRect(x - 1, y, 1, 1);
		graphics.fillRect(x + 3, y, 1, 1);
		graphics.setColor(new Color(GOLD.getRed(), GOLD.getGreen(), GOLD.getBlue(), alpha / 2));
		graphics.fillRect(x + 1, y - 2, 1, 1);
	}
}

