package com.herbrunhelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Shows where to go on the minimap: a marker on the target when it's on the minimap, otherwise an
 * arrow near the edge pointing towards it. Works without the Shortest Path plugin.
 */
class MinimapArrowOverlay extends Overlay
{
	/** How far out (tiles) to place the edge arrow; stays inside the minimap at any zoom. */
	private static final int EDGE_TILES = 13;

	private final Client client;
	private final HerbRunPlugin plugin;
	private final HerbRunConfig config;

	@Inject
	MinimapArrowOverlay(Client client, HerbRunPlugin plugin, HerbRunConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		WorldPoint target = plugin.getNavTarget();
		Player player = client.getLocalPlayer();
		if (target == null || player == null)
		{
			return null;
		}
		WorldPoint me = player.getWorldLocation();
		LocalPoint meLocal = player.getLocalLocation();
		if (me == null || meLocal == null || me.getPlane() != target.getPlane())
		{
			return null;
		}
		Point centre = Perspective.localToMinimap(client, meLocal);
		if (centre == null)
		{
			return null;
		}
		Color color = config.patchColor();
		if (!plugin.showArrow())
		{
			return null;
		}
		int dx = target.getX() - me.getX();
		int dy = target.getY() - me.getY();
		double dist = Math.sqrt((double) dx * dx + (double) dy * dy);
		if (dist < 1 || dist > 120)
		{
			return null; // further than that you teleport first, so no arrow across the map
		}
		if (dist <= EDGE_TILES)
		{
			// On the minimap: a ring marker on the spot.
			LocalPoint lp = LocalPoint.fromWorld(client, target);
			Point p = lp == null ? null : Perspective.localToMinimap(client, lp);
			if (p != null)
			{
				graphics.setStroke(new BasicStroke(2));
				graphics.setColor(Color.BLACK);
				graphics.drawOval(p.getX() - 5, p.getY() - 5, 10, 10);
				graphics.setColor(color);
				graphics.fillOval(p.getX() - 4, p.getY() - 4, 8, 8);
			}
			return null;
		}
		// Off the minimap: an arrow part-way out, pointing towards the target. Working it out from
		// a real tile in that direction keeps it right however the minimap is turned.
		double ux = dx / dist;
		double uy = dy / dist;
		WorldPoint towards = new WorldPoint(me.getX() + (int) Math.round(ux * EDGE_TILES),
			me.getY() + (int) Math.round(uy * EDGE_TILES), me.getPlane());
		LocalPoint lp = LocalPoint.fromWorld(client, towards);
		Point tip = lp == null ? null : Perspective.localToMinimap(client, lp);
		if (tip == null)
		{
			return null;
		}
		double ax = tip.getX() - centre.getX();
		double ay = tip.getY() - centre.getY();
		double len = Math.sqrt(ax * ax + ay * ay);
		if (len < 1)
		{
			return null;
		}
		ax /= len;
		ay /= len;
		double px = -ay;
		double py = ax;
		int tx = tip.getX();
		int ty = tip.getY();
		int[] xs = {tx, (int) (tx - ax * 10 + px * 6), (int) (tx - ax * 10 - px * 6)};
		int[] ys = {ty, (int) (ty - ay * 10 + py * 6), (int) (ty - ay * 10 - py * 6)};
		Polygon arrow = new Polygon(xs, ys, 3);
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(Color.BLACK);
		graphics.draw(arrow);
		graphics.setColor(color);
		graphics.fill(arrow);
		return null;
	}
}

package com.herbrunhelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * A small box at the top of the screen: what to do right now (dial this code, pay the gardener,
 * plant this seed...) and the stop after that, so the sidebar can stay closed. Thanks to Romte1, whose
 * on-screen step box (pull request #1) gave the idea.
 */
class NowNextOverlay extends OverlayPanel
{
	private static final Color TITLE = new Color(120, 200, 90);
	private static final Color NOW = new Color(255, 214, 90);
	private static final Color NEXT = new Color(190, 190, 190);
	private static final int WIDTH = 240;

	private final Client client;
	private final HerbRunPlugin plugin;
	private final HerbRunConfig config;

	@Inject
	NowNextOverlay(Client client, HerbRunPlugin plugin, HerbRunConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Hidden while the bank is open, so it doesn't cover it; back as soon as it closes. */
	private boolean bankOpen()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		return bank != null && !bank.isHidden();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String now = plugin.getNowText();
		if (!config.showNowNext() || now == null || bankOpen())
		{
			return null;
		}
		String stop = plugin.getStopCountText();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Farm run" + (stop == null ? "" : "  " + stop)).color(TITLE).build());
		panelComponent.getChildren().add(LineComponent.builder().left("Now: " + now).leftColor(NOW).build());
		String next = plugin.getNextText();
		if (next != null)
		{
			panelComponent.getChildren().add(LineComponent.builder().left("Next: " + next).leftColor(NEXT).build());
		}
		panelComponent.setPreferredSize(new Dimension(WIDTH, 0));
		return super.render(graphics);
	}
}

package com.herbrunhelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Highlights the next patch on the ground. It snaps to the real patch object when one is
 * loaded near the target; otherwise it outlines the target tile.
 */
public class PatchNavigationOverlay extends Overlay
{
	private final Client client;
	private final HerbRunPlugin plugin;
	private final HerbRunConfig config;

	@Inject
	PatchNavigationOverlay(Client client, HerbRunPlugin plugin, HerbRunConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		renderGardener(graphics);
		FarmPatch next = plugin.getNextPatch();
		if (!config.highlightPatch() || next == null)
		{
			return null;
		}
		WorldPoint target = plugin.tileFor(next);
		Color color = config.patchColor();
		Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), 50);

		// Heading to a fairy ring first: mark the ring and say what to dial.
		WorldPoint ring = plugin.getNavRing();
		if (ring != null)
		{
			LocalPoint lp = LocalPoint.fromWorld(client, ring);
			if (lp == null)
			{
				return null;
			}
			net.runelite.api.TileObject ringObj = plugin.getNavRingObject();
			Shape ringHull = ringObj == null ? null : ringObj.getClickbox();
			if (ringHull == null && ringObj != null)
			{
				ringHull = ringObj.getCanvasTilePoly();
			}
			if (ringHull != null)
			{
				graphics.setColor(fill);
				graphics.fill(ringHull);
				graphics.setColor(color);
				graphics.setStroke(new BasicStroke(2));
				graphics.draw(ringHull);
				lp = ringObj.getLocalLocation();
			}
			else
			{
				Polygon tile = Perspective.getCanvasTilePoly(client, lp);
				if (tile != null)
				{
					OverlayUtil.renderPolygon(graphics, tile, color);
				}
			}
			String text = plugin.getNavRingLabel();
			Point textLoc = Perspective.getCanvasTextLocation(client, graphics, lp, text, 150);
			if (textLoc != null)
			{
				OverlayUtil.renderTextLocation(graphics, textLoc, text, color);
				if (ringObj != null && !gardenerArrow)
				{
					drawArrow(graphics, textLoc, graphics.getFontMetrics().stringWidth(text), color);
				}
			}
			return null;
		}

		// The real patch object (matched by its farming varbit), when it's loaded.
		GameObject best = plugin.objectFor(next);

		LocalPoint labelPoint;
		if (best != null)
		{
			// Some grown trees have no model outline: fall back to the click area, then the
			// patch's floor area, so the patch is always marked.
			Shape hull = best.getConvexHull();
			if (hull == null)
			{
				hull = best.getClickbox();
			}
			if (hull == null)
			{
				LocalPoint centre = best.getLocalLocation();
				int size = next.getType().patchSize();
				hull = centre == null ? null : Perspective.getCanvasTileAreaPoly(client, centre, size);
			}
			if (hull != null)
			{
				graphics.setColor(fill);
				graphics.fill(hull);
				graphics.setColor(color);
				graphics.setStroke(new BasicStroke(2));
				graphics.draw(hull);
			}
			labelPoint = best.getLocalLocation();
		}
		else
		{
			labelPoint = LocalPoint.fromWorld(client, target);
			if (labelPoint == null)
			{
				return null; // not in the loaded area yet
			}
			Polygon tile = Perspective.getCanvasTilePoly(client, labelPoint);
			if (tile != null)
			{
				OverlayUtil.renderPolygon(graphics, tile, color);
			}
		}

		if (labelPoint != null)
		{
			String text = next.getDisplayName();
			Point textLoc = Perspective.getCanvasTextLocation(client, graphics, labelPoint, text, 150);
			if (textLoc != null)
			{
				OverlayUtil.renderTextLocation(graphics, textLoc, text, color);
				// The arrow only goes on the real patch once it's loaded, never on a guessed tile.
				if (best != null && !gardenerArrow)
				{
					drawArrow(graphics, textLoc, graphics.getFontMetrics().stringWidth(text), color);
				}
			}
		}
		return null;
	}

	/** Set each frame: the arrow is on the gardener instead of the patch. */
	private boolean gardenerArrow;

	/**
	 * A steady arrow pointing down at a label, drawn by this plugin (the game's own hint arrow
	 * blinks and drifts). {@code textLoc} is the label's baseline-left point.
	 */
	private void drawArrow(Graphics2D graphics, Point textLoc, int textWidth, Color color)
	{
		if (!plugin.showArrow())
		{
			return;
		}
		int cx = textLoc.getX() + textWidth / 2;
		int tipY = textLoc.getY() - graphics.getFontMetrics().getAscent() - 4;
		int[] xs = {cx, cx - 9, cx - 4, cx - 4, cx + 4, cx + 4, cx + 9};
		int[] ys = {tipY, tipY - 10, tipY - 10, tipY - 22, tipY - 22, tipY - 10, tipY - 10};
		Polygon arrow = new Polygon(xs, ys, xs.length);
		graphics.setStroke(new BasicStroke(2));
		graphics.setColor(Color.BLACK);
		graphics.draw(arrow);
		graphics.setColor(color);
		graphics.fill(arrow);
	}

	/** Outlines the gardener you need to pay, with what to give them. */
	private void renderGardener(Graphics2D graphics)
	{
		gardenerArrow = false;
		net.runelite.api.NPC npc = plugin.getGardenerToPay();
		String text = plugin.getPayLabel();
		if (npc == null || text == null)
		{
			return;
		}
		gardenerArrow = true;
		Color gold = new Color(255, 200, 60);
		Shape hull = npc.getConvexHull();
		if (hull != null)
		{
			graphics.setColor(new Color(255, 200, 60, 40));
			graphics.fill(hull);
			graphics.setColor(gold);
			graphics.setStroke(new BasicStroke(2));
			graphics.draw(hull);
		}
		LocalPoint lp = npc.getLocalLocation();
		if (lp != null)
		{
			Point textLoc = Perspective.getCanvasTextLocation(client, graphics, lp, text, npc.getLogicalHeight() + 40);
			if (textLoc != null)
			{
				OverlayUtil.renderTextLocation(graphics, textLoc, text, gold);
				drawArrow(graphics, textLoc, graphics.getFontMetrics().stringWidth(text), gold);
			}
		}
	}
}

/*
 * Decoding of farming patch varbit values.
 *
 * The data table (patch-states.tsv) is generated by scripts/generate_patch_states.py from
 * RuneLite's Time Tracking plugin (PatchImplementation), Copyright (c) 2019 Abex,
 * BSD 2-Clause; see NOTICE.
 */
package com.herbrunhelper;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * Turns a patch's varbit value into what's growing there. Pure Java so it can be tested.
 */
public final class PatchStates
{
	public enum State
	{
		/** Weeds or bare soil: needs raking/planting. */
		EMPTY,
		GROWING,
		/** Ready to harvest, or (trees) fully grown and waiting for check-health / chopping. */
		READY,
		/** A tree that's been chopped: stump left (clear it, or it regrows). */
		STUMP,
		DISEASED,
		DEAD,
		UNKNOWN
	}

	public static final class Decoded
	{
		public final State state;
		/** Null for weeds, dead herbs (the game doesn't say which) or crops the plugin doesn't plant. */
		public final Crop crop;
		public final int stage;
		/** Tree still standing that must be chopped down before replanting. */
		public final boolean fell;
		/** Grown tree (or fruit tree, or hardwood) whose health hasn't been checked yet. */
		public final boolean checkHealth;

		Decoded(State state, Crop crop, int stage, boolean fell)
		{
			this(state, crop, stage, fell, false);
		}

		Decoded(State state, Crop crop, int stage, boolean fell, boolean checkHealth)
		{
			this.state = state;
			this.crop = crop;
			this.stage = stage;
			this.fell = fell;
			this.checkHealth = checkHealth;
		}
	}

	private static final class Row
	{
		final int lo;
		final int hi;
		final String crop;
		final String state;
		final int stage;
		final int step;
		/** check = ready for check-health, chop = grown tree to chop down, stump = tree stump. */
		final String flag;

		Row(String[] c)
		{
			lo = Integer.parseInt(c[1]);
			hi = Integer.parseInt(c[2]);
			crop = c[3];
			state = c[4];
			stage = Integer.parseInt(c[5]);
			step = Integer.parseInt(c[6]);
			flag = c[7];
		}
	}

	private static volatile PatchStates instance;

	private final Map<PatchType, List<Row>> rows = new EnumMap<>(PatchType.class);

	private PatchStates(InputStream in) throws IOException
	{
		for (PatchType t : PatchType.values())
		{
			rows.put(t, new ArrayList<>());
		}
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}
				String[] c = line.split("\t");
				for (PatchType t : PatchType.values())
				{
					if (t.getTableName().equals(c[0]))
					{
						rows.get(t).add(new Row(c));
					}
				}
			}
		}
	}

	/** Shared table loaded from the plugin's resources. */
	public static PatchStates get()
	{
		if (instance == null)
		{
			synchronized (PatchStates.class)
			{
				if (instance == null)
				{
					instance = load(PatchStates.class.getResourceAsStream("patch-states.tsv"));
				}
			}
		}
		return instance;
	}

	public static PatchStates load(InputStream in)
	{
		if (in == null)
		{
			throw new IllegalStateException("patch-states.tsv missing from resources");
		}
		try
		{
			return new PatchStates(in);
		}
		catch (IOException e)
		{
			throw new UncheckedIOException(e);
		}
	}

	public Decoded decode(PatchType type, int value)
	{
		for (Row row : rows.get(type))
		{
			if (value < row.lo || value > row.hi)
			{
				continue;
			}
			int stage = row.stage + row.step * (value - row.lo);
			Crop crop = Crop.fromTableName(row.crop);
			if ("WEEDS".equals(row.crop))
			{
				return new Decoded(State.EMPTY, null, stage, false);
			}
			switch (row.state)
			{
				case "GROWING":
					if ("check".equals(row.flag))
					{
						return new Decoded(State.READY, crop, stage, false, true);
					}
					return new Decoded(State.GROWING, crop, stage, false);
				case "HARVESTABLE":
					if ("stump".equals(row.flag))
					{
						return new Decoded(State.STUMP, crop, stage, false);
					}
					return new Decoded(State.READY, crop, stage, "chop".equals(row.flag));
				case "DISEASED":
					return new Decoded(State.DISEASED, crop, stage, false);
				case "DEAD":
					return new Decoded(State.DEAD, crop, stage, false);
				default:
					return new Decoded(State.UNKNOWN, crop, stage, false);
			}
		}
		return new Decoded(State.UNKNOWN, null, 0, false);
	}
}

package com.herbrunhelper;

import java.util.EnumMap;
import java.util.Map;

/**
 * Remembers what was planted where and when, and works out countdowns.
 * Pure Java; the plugin persists it per account with {@link #serialize()}.
 */
public final class PatchTimers
{
	/** What we saw at a patch when there's no countdown to show. */
	public enum Status
	{
		EMPTY("empty"),
		WEEDS("weeds"),
		GROWING_UNKNOWN("growing"),
		STUMP("stump"),
		DISEASED("diseased!"),
		DEAD("dead");

		private final String label;

		Status(String label)
		{
			this.label = label;
		}

		public String getLabel()
		{
			return label;
		}
	}

	public static final class Planting
	{
		public final Crop crop;
		public final long plantedAtMillis;

		Planting(Crop crop, long plantedAtMillis)
		{
			this.crop = crop;
			this.plantedAtMillis = plantedAtMillis;
		}

		public long readyAtMillis()
		{
			return plantedAtMillis + crop.getGrowthMinutes() * 60_000L;
		}

		public long millisLeft(long now)
		{
			return Math.max(0, readyAtMillis() - now);
		}

		public boolean isReady(long now)
		{
			return now >= readyAtMillis();
		}
	}

	private final EnumMap<FarmPatch, Planting> plantings = new EnumMap<>(FarmPatch.class);
	private final EnumMap<FarmPatch, Status> statuses = new EnumMap<>(FarmPatch.class);
	private final EnumMap<FarmPatch, Crop> statusCrops = new EnumMap<>(FarmPatch.class);

	public synchronized void planted(FarmPatch patch, Crop crop, long now)
	{
		plantings.put(patch, new Planting(crop, now));
		statuses.remove(patch);
		statusCrops.remove(patch);
	}

	/** Set a timer from an observed ready time (e.g. from the patch's growth stage). */
	public synchronized void syncReadyAt(FarmPatch patch, Crop crop, long readyAt)
	{
		plantings.put(patch, new Planting(crop, readyAt - crop.getGrowthMinutes() * 60_000L));
		statuses.remove(patch);
		statusCrops.remove(patch);
	}

	/** Record a state with no countdown (empty, diseased, dead, growing-time-unknown). */
	public synchronized void setStatus(FarmPatch patch, Status status, Crop crop)
	{
		plantings.remove(patch);
		statuses.put(patch, status);
		if (crop != null)
		{
			statusCrops.put(patch, crop);
		}
		else
		{
			statusCrops.remove(patch);
		}
	}

	public synchronized Status getStatus(FarmPatch patch)
	{
		return statuses.get(patch);
	}

	public synchronized Crop getStatusCrop(FarmPatch patch)
	{
		return statusCrops.get(patch);
	}

	public synchronized Planting get(FarmPatch patch)
	{
		return plantings.get(patch);
	}

	public synchronized void clear(FarmPatch patch)
	{
		plantings.remove(patch);
		statuses.remove(patch);
		statusCrops.remove(patch);
	}

	public synchronized Map<FarmPatch, Planting> snapshot()
	{
		return new EnumMap<>(plantings);
	}

	/** A patch needs visiting unless something is known to be growing there. */
	public synchronized boolean needsVisit(FarmPatch patch, long now)
	{
		Planting p = plantings.get(patch);
		if (p != null)
		{
			return p.isReady(now);
		}
		return statuses.get(patch) != Status.GROWING_UNKNOWN;
	}

	/** True if any patch has a timer or a status. */
	public synchronized boolean hasAnything()
	{
		return !plantings.isEmpty() || !statuses.isEmpty();
	}

	public synchronized String serialize()
	{
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<FarmPatch, Planting> e : plantings.entrySet())
		{
			if (sb.length() > 0)
			{
				sb.append(';');
			}
			sb.append(e.getKey().name()).append(':').append(e.getValue().crop.name())
				.append(':').append(e.getValue().plantedAtMillis);
		}
		return sb.toString();
	}

	public synchronized void load(String data)
	{
		plantings.clear();
		statuses.clear();
		statusCrops.clear();
		if (data == null || data.isEmpty())
		{
			return;
		}
		for (String entry : data.split(";"))
		{
			String[] parts = entry.split(":");
			if (parts.length != 3)
			{
				continue;
			}
			try
			{
				plantings.put(FarmPatch.valueOf(parts[0]),
					new Planting(Crop.valueOf(parts[1]), Long.parseLong(parts[2])));
			}
			catch (IllegalArgumentException ignored)
			{
				// Patch/crop renamed in a newer version; skip it.
			}
		}
	}

	/** "2h 14m" when an hour or more is left, otherwise "14m 05s". */
	public static String formatDuration(long millis)
	{
		long totalSeconds = Math.max(0, millis) / 1000;
		long h = totalSeconds / 3600;
		long m = (totalSeconds % 3600) / 60;
		long s = totalSeconds % 60;
		if (h > 0)
		{
			return h + "h " + String.format("%02d", m) + "m";
		}
		return m + "m " + String.format("%02d", s) + "s";
	}
}

package com.herbrunhelper;

/**
 * Kinds of patch, each its own run. Growth tick lengths and table names match RuneLite's Time
 * Tracking plugin (Produce / PatchImplementation); how each is cleared follows the OSRS Wiki.
 */
public enum PatchType
{
	HERB("Herbs", "HERB", 20, "includeHerbs", Clear.HARVEST),
	ALLOTMENT("Allotments", "ALLOTMENT", 10, "includeAllotments", Clear.HARVEST),
	TREE("Trees", "TREE", 40, "includeTrees", Clear.GARDENER),
	FRUIT_TREE("Fruit trees", "FRUIT_TREE", 160, "includeFruitTrees", Clear.GARDENER),
	HARDWOOD("Hardwood", "HARDWOOD_TREE", 640, "includeHardwood", Clear.GARDENER),
	BUSH("Bushes", "BUSH", 20, "includeBushes", Clear.SPADE),
	HOPS("Hops", "HOPS", 10, "includeHops", Clear.HARVEST),
	CACTUS("Cactus", "CACTUS", 80, "includeCactus", Clear.SPADE),
	CALQUAT("Calquat", "CALQUAT", 160, "includeCalquat", Clear.GARDENER),
	SPIRIT_TREE("Spirit trees", "SPIRIT_TREE", 320, "includeSpiritTrees", Clear.SPADE),
	CELASTRUS("Celastrus", "CELASTRUS", 160, "includeCelastrus", Clear.SPADE),
	REDWOOD("Redwood", "REDWOOD", 640, "includeRedwood", Clear.SPADE);

	/** How a grown crop is got rid of before replanting. */
	public enum Clear
	{
		/** Harvesting empties the patch (herbs, allotments, hops). */
		HARVEST,
		/** Pay the gardener coins to chop it down. */
		GARDENER,
		/** Dig it up with a spade (after harvesting or chopping, where there's anything to take). */
		SPADE
	}

	private final String displayName;
	/** Name used for this type in patch-states.tsv. */
	private final String tableName;
	/** Minutes between growth ticks (a crop can have its own; see Crop). */
	private final int tickMinutes;
	/** Settings key for "include this run". */
	private final String configKey;
	private final Clear clear;

	PatchType(String displayName, String tableName, int tickMinutes, String configKey, Clear clear)
	{
		this.displayName = displayName;
		this.tableName = tableName;
		this.tickMinutes = tickMinutes;
		this.configKey = configKey;
		this.clear = clear;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	public String getTableName()
	{
		return tableName;
	}

	public int getTickMinutes()
	{
		return tickMinutes;
	}

	public String getConfigKey()
	{
		return configKey;
	}

	public Clear getClear()
	{
		return clear;
	}

	/**
	 * Grown crops that stay in the patch: their health is checked when grown, and they must be
	 * cleared (gardener or spade) before replanting. Everything but herbs, allotments and hops.
	 */
	public boolean isTreeLike()
	{
		return clear != Clear.HARVEST;
	}

	/** Planted as a sapling (grown from a seed in a plant pot) rather than seeds. */
	public boolean usesSaplings()
	{
		return this == TREE || this == FRUIT_TREE || this == HARDWOOD || this == CALQUAT
			|| this == SPIRIT_TREE || this == CELASTRUS || this == REDWOOD;
	}

	/** Gardeners can be paid to protect these crops. */
	public boolean hasGardenerPayment()
	{
		return this != HERB;
	}

	/** Seeds that stack in one inventory slot (not saplings). */
	public boolean seedsStack()
	{
		return !usesSaplings();
	}

	/** Tiles across a typical patch of this type (for outlines when the game gives none). */
	public int patchSize()
	{
		return usesSaplings() ? 3 : 2;
	}

	/** "seeds" or "saplings". */
	public String seedWord()
	{
		return usesSaplings() ? "saplings" : "seeds";
	}

	/** Singular patch name for sentences: "herb", "bush", "spirit tree"... */
	public String patchName()
	{
		switch (this)
		{
			case HERB:
				return "herb";
			case ALLOTMENT:
				return "allotment";
			case TREE:
				return "tree";
			case FRUIT_TREE:
				return "fruit tree";
			case HARDWOOD:
				return "hardwood";
			case BUSH:
				return "bush";
			case HOPS:
				return "hops";
			case CACTUS:
				return "cactus";
			case CALQUAT:
				return "calquat";
			case SPIRIT_TREE:
				return "spirit tree";
			case CELASTRUS:
				return "celastrus";
			default:
				return "redwood";
		}
	}
}

package com.herbrunhelper;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.SpriteID;
import net.runelite.api.widgets.Widget;

/**
 * Spaces out the items while the bank shows the Farm run tag: 7 wider columns instead of the bank's
 * 8, and taller rows so the "15 noted" / "3 unnoted" label under each item has room, and the bank's tab
 * divider lines hidden. Only moves the item widgets on screen; each keeps its item, so clicking
 * it withdraws exactly as normal. (Laying out the bank tag's item widgets follows the approach
 * in Romte1's Farm run bank view and Quest Helper.)
 */
final class RunBankLayout
{
	static final int PER_ROW = 7;
	static final int X_SPACING = 56;
	static final int Y_SPACING = 54;
	private static final int TOP = 8;

	private RunBankLayout()
	{
	}

	/** Called on the client thread after the bank has finished building with the run tag open. */
	static void apply(Client client)
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null || items.isHidden())
		{
			return;
		}
		Widget[] children = items.getDynamicChildren();
		if (children == null)
		{
			return;
		}
		List<Widget> shown = new ArrayList<>();
		int startX = Integer.MAX_VALUE;
		for (Widget child : children)
		{
			if (child == null || child.isHidden())
			{
				continue;
			}
			if (child.getItemId() > 0)
			{
				shown.add(child);
				startX = Math.min(startX, child.getOriginalX());
			}
			else if (child.getSpriteId() == SpriteID.TRADEBACKING_DARK)
			{
				child.setHidden(true); // the line between bank tabs
			}
		}
		if (shown.isEmpty())
		{
			return;
		}
		// Keep the bank's own order (top to bottom, left to right).
		shown.sort(Comparator.comparingInt(Widget::getOriginalY).thenComparingInt(Widget::getOriginalX));
		for (int i = 0; i < shown.size(); i++)
		{
			Widget w = shown.get(i);
			w.setOriginalX(startX + (i % PER_ROW) * X_SPACING);
			w.setOriginalY(TOP + (i / PER_ROW) * Y_SPACING);
			w.revalidate();
		}
		int rows = (shown.size() + PER_ROW - 1) / PER_ROW;
		int height = Math.max(items.getHeight(), TOP + rows * Y_SPACING);
		int scroll = Math.min(items.getScrollY(), Math.max(0, height - items.getHeight()));
		items.setScrollHeight(height);
		items.setScrollY(scroll);
		client.runScript(ScriptID.UPDATE_SCROLLBAR, InterfaceID.Bankmain.SCROLLBAR, InterfaceID.Bankmain.ITEMS, scroll);
	}
}

package com.herbrunhelper;

import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.plugins.banktags.BankTag;

/**
 * The "Farm run" bank tag: the bank items this run needs. Opened through RuneLite's Bank Tags,
 * so the bank shows just these items and you withdraw them with normal clicks.
 */
final class RunBankTag implements BankTag
{
	static final String NAME = "farm run optimizer";

	private volatile Set<Integer> ids = Collections.emptySet();

	/** True if the items changed. */
	boolean set(Set<Integer> next)
	{
		if (ids.equals(next))
		{
			return false;
		}
		ids = Collections.unmodifiableSet(new HashSet<>(next));
		return true;
	}

	@Override
	public boolean contains(int itemId)
	{
		return ids.contains(itemId);
	}
}

package com.herbrunhelper;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Keeps a log of your farm runs: what you harvested, what the seeds cost, and the profit at
 * Grand Exchange prices. A run ends after a while with no farming. Pure Java.
 */
public final class RunHistory
{
	public static final int MAX_RUNS = 30;
	/** A run ends after this long without harvesting or planting. */
	public static final long IDLE_END_MS = 20 * 60_000L;

	public static final class Run
	{
		public long start;
		public long end;
		public final Set<FarmPatch> patches = EnumSet.noneOf(FarmPatch.class);
		/** Produce name -> amount. */
		public final Map<String, Integer> produce = new LinkedHashMap<>();
		public long value;
		public long cost;
		/** Herbs picked and herb patches harvested, to learn your average yield. */
		public int herbsPicked;
		public int herbPatches;
		/** Farming XP gained at the patches during the run. */
		public long xp;

		public long profit()
		{
			return value - cost;
		}

		public boolean isEmpty()
		{
			return patches.isEmpty() && produce.isEmpty() && xp == 0;
		}
	}

	private final List<Run> runs = new ArrayList<>();
	private Run current;
	private long lastActivity;
	private final Set<FarmPatch> harvestedHerbs = EnumSet.noneOf(FarmPatch.class);
	private final Set<FarmPatch> paidFor = EnumSet.noneOf(FarmPatch.class);

	public synchronized Run current()
	{
		return current;
	}

	public synchronized List<Run> runs()
	{
		return Collections.unmodifiableList(new ArrayList<>(runs));
	}

	private Run active(long now)
	{
		if (current == null)
		{
			current = new Run();
			current.start = now;
			harvestedHerbs.clear();
			paidFor.clear();
		}
		lastActivity = now;
		current.end = now;
		return current;
	}

	/**
	 * You picked some produce at a patch. The seed that grew it is counted once per patch, so a
	 * run's profit is what you harvested minus what those crops cost to plant.
	 */
	public synchronized void harvested(FarmPatch patch, String name, int qty, long unitPrice, boolean herb,
		long seedPrice, long now)
	{
		Run r = active(now);
		if (paidFor.add(patch))
		{
			r.cost += Math.max(0L, seedPrice);
		}
		r.patches.add(patch);
		r.produce.merge(name, qty, Integer::sum);
		r.value += qty * Math.max(0L, unitPrice);
		if (herb)
		{
			r.herbsPicked += qty;
			if (harvestedHerbs.add(patch))
			{
				r.herbPatches++;
			}
		}
	}

	/** Farming XP gained while at a patch (checking health, harvesting, planting, compost). */
	public synchronized void gainedXp(long amount, long now)
	{
		if (amount > 0)
		{
			active(now).xp += amount;
		}
	}

	/** You planted a seed or sapling (its cost is counted when you harvest what it grew). */
	public synchronized void planted(FarmPatch patch, long now)
	{
		Run r = active(now);
		r.patches.add(patch);
	}

	/** Ends the current run if you've stopped farming. Returns true if a run was saved. */
	public synchronized boolean tick(long now)
	{
		if (current != null && now - lastActivity > IDLE_END_MS)
		{
			return finish();
		}
		return false;
	}

	public synchronized boolean finish()
	{
		Run r = current;
		current = null;
		if (r == null || r.isEmpty())
		{
			return false;
		}
		runs.add(0, r);
		while (runs.size() > MAX_RUNS)
		{
			runs.remove(runs.size() - 1);
		}
		return true;
	}

	public synchronized void clear()
	{
		runs.clear();
		current = null;
	}

	/** Your average herbs per patch, or the default until there are a few patches logged. */
	public synchronized double averageHerbYield()
	{
		int herbs = 0;
		int patches = 0;
		for (Run r : runs)
		{
			herbs += r.herbsPicked;
			patches += r.herbPatches;
		}
		return patches >= 3 ? (double) herbs / patches : HerbPrices.DEFAULT_YIELD;
	}

	public synchronized long totalProfit()
	{
		long t = 0;
		for (Run r : runs)
		{
			t += r.profit();
		}
		return t;
	}

	// ---------------------------------------------------------------- saving

	/** One run per line: start|end|value|cost|herbsPicked|herbPatches|PATCH,PATCH|name=qty;name=qty|xp */
	public synchronized String serialize()
	{
		StringBuilder sb = new StringBuilder();
		for (Run r : runs)
		{
			line(sb, r);
		}
		return sb.toString();
	}

	/** The run in progress, so it survives closing the client mid-run. Empty when there's none. */
	public synchronized String serializeCurrent()
	{
		StringBuilder sb = new StringBuilder();
		if (current != null && !current.isEmpty())
		{
			line(sb, current);
		}
		return sb.toString();
	}

	/** Restores the run in progress; one that's been idle too long is filed into the history. */
	public synchronized void loadCurrent(String raw, long now)
	{
		current = null;
		List<Run> parsed = parse(raw);
		if (parsed.isEmpty())
		{
			return;
		}
		Run r = parsed.get(0);
		if (now - r.end > IDLE_END_MS)
		{
			runs.add(0, r);
			while (runs.size() > MAX_RUNS)
			{
				runs.remove(runs.size() - 1);
			}
		}
		else
		{
			current = r;
			lastActivity = r.end;
		}
	}

	private static void line(StringBuilder sb, Run r)
	{
		{
			sb.append(r.start).append('|').append(r.end).append('|').append(r.value).append('|').append(r.cost)
				.append('|').append(r.herbsPicked).append('|').append(r.herbPatches).append('|');
			boolean first = true;
			for (FarmPatch p : r.patches)
			{
				sb.append(first ? "" : ",").append(p.name());
				first = false;
			}
			sb.append('|');
			first = true;
			for (Map.Entry<String, Integer> e : r.produce.entrySet())
			{
				sb.append(first ? "" : ";").append(e.getKey().replace("|", "").replace(";", "").replace("=", ""))
					.append('=').append(e.getValue());
				first = false;
			}
			sb.append('|').append(r.xp);
			sb.append('\n');
		}
	}

	public synchronized void load(String raw)
	{
		runs.clear();
		runs.addAll(parse(raw));
	}

	private static List<Run> parse(String raw)
	{
		List<Run> out = new ArrayList<>();
		if (raw == null)
		{
			return out;
		}
		for (String line : raw.split("\n"))
		{
			String[] f = line.split("\\|", -1);
			if (f.length < 8)
			{
				continue;
			}
			try
			{
				Run r = new Run();
				r.start = Long.parseLong(f[0]);
				r.end = Long.parseLong(f[1]);
				r.value = Long.parseLong(f[2]);
				r.cost = Long.parseLong(f[3]);
				r.herbsPicked = Integer.parseInt(f[4]);
				r.herbPatches = Integer.parseInt(f[5]);
				for (String p : f[6].split(","))
				{
					try
					{
						if (!p.isEmpty())
						{
							r.patches.add(FarmPatch.valueOf(p));
						}
					}
					catch (IllegalArgumentException ignored)
					{
						// patch renamed in a later version
					}
				}
				for (String kv : f[7].split(";"))
				{
					int eq = kv.lastIndexOf('=');
					if (eq > 0)
					{
						r.produce.put(kv.substring(0, eq), Integer.parseInt(kv.substring(eq + 1)));
					}
				}
				if (f.length > 8 && !f[8].isEmpty())
				{
					r.xp = Long.parseLong(f[8]);
				}
				out.add(r);
			}
			catch (NumberFormatException ignored)
			{
				// skip a damaged line
			}
		}
		return out;
	}
}

package com.herbrunhelper;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/** The result of planning: what's unlocked, the route, what to bring, and any bank stops. */
public final class RunPlan
{
	public static final class RouteStep
	{
		public final FarmPatch patch;
		/** The teleport used, or null for a walk / nothing available. */
		public final Teleport teleport;
		public final String teleportLabel;
		/** Exact item name to bring, or null for a spell / walk / no teleport found. */
		public final String teleportItem;
		public final boolean hasTeleport;
		/** For walks: the patch this walk starts from. */
		public FarmPatch anchor;

		/** What to plant here, or null if you're out of seeds/saplings. */
		public Crop crop;
		/** Planted already on this run: still shows compost/payment, but nothing to bring for it. */
		public boolean done;
		/** Compost to use here (an item name, or a bottomless bucket), or null. */
		public String compost;
		/** Gardener payment for this stop (trees), or null. */
		public String paymentItem;
		public int paymentQuantity;
		/** Coins for the gardener to clear a grown tree. */
		public int coins;

		RouteStep(FarmPatch patch, Teleport teleport, String teleportLabel, String teleportItem, boolean hasTeleport)
		{
			this.patch = patch;
			this.teleport = teleport;
			this.teleportLabel = teleportLabel;
			this.teleportItem = teleportItem;
			this.hasTeleport = hasTeleport;
		}
	}

	public static final class Withdrawal
	{
		public final String itemName;
		public final int quantity;
		public final String note;

		Withdrawal(String itemName, int quantity, String note)
		{
			this.itemName = itemName;
			this.quantity = quantity;
			this.note = note;
		}
	}

	/** A bank visit in the middle of the run because everything won't fit in one inventory. */
	public static final class BankStop
	{
		/** Index into route: the bank comes just before this stop. */
		public final int beforeStep;
		public final String bank;
		public final List<Withdrawal> withdrawals = new ArrayList<>();

		BankStop(int beforeStep, String bank)
		{
			this.beforeStep = beforeStep;
			this.bank = bank;
		}
	}

	public int farmingLevel;
	public boolean bankKnown;
	/** Best crop you can plant, per patch type. */
	public final Map<PatchType, Crop> best = new EnumMap<>(PatchType.class);
	/** Next crop you'll unlock, per patch type. */
	public final Map<PatchType, Crop> next = new EnumMap<>(PatchType.class);
	public final List<FarmPatch> lockedPatches = new ArrayList<>();
	/** Every patch your quests/levels unlock, whether or not its run is on. */
	public final java.util.Set<FarmPatch> unlocked = java.util.EnumSet.noneOf(FarmPatch.class);
	/** Unlocked patches you've unticked. */
	public final List<FarmPatch> skippedPatches = new ArrayList<>();
	public final List<RouteStep> route = new ArrayList<>();
	/** What to take from the bank at the start. */
	public final List<Withdrawal> withdrawals = new ArrayList<>();
	public final List<BankStop> bankStops = new ArrayList<>();
	public final List<String> warnings = new ArrayList<>();
	/** Friendly reminders, e.g. pot your tree seeds for later runs. */
	public final List<String> tips = new ArrayList<>();
	/** Availability of every teleport, for the Travel section. */
	public final Map<Teleport, Teleport.Availability> availability = new EnumMap<>(Teleport.class);
	/** Inventory slots the first leg needs (for the "fits" line). */
	public int slotsNeeded;
	/** About how much Farming XP the run gives (harvests / health checks, planting, compost). */
	public double estimatedXp;
}

package com.herbrunhelper;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Pure planning logic with no RuneLite dependencies, so it can be unit tested on its own.
 *
 * Input: Farming level, which patches the player has unlocked, and every item they own
 * (bank + inventory + equipment) as exact item name -> quantity.
 */
public final class RunPlanner
{
	public static final class Options
	{
		public final Set<PatchType> runs = EnumSet.of(PatchType.HERB, PatchType.TREE);
		public boolean useCompost = true;
		public boolean bringRake = true;
		public boolean payGardeners = true;
		public boolean bankKnown = true;
		public int inventorySlots = 28;
		/** Crops you've unticked: never planted. */
		public Set<Crop> disabledCrops = EnumSet.noneOf(Crop.class);
		/** Patches you've unticked: skipped. */
		public Set<FarmPatch> disabledPatches = EnumSet.noneOf(FarmPatch.class);
		/** Patches with something of yours growing or ready: always visited, and get seeds first. */
		public Set<FarmPatch> usedPatches = EnumSet.noneOf(FarmPatch.class);
		/** Crops in the order to plant them (e.g. most profitable first); empty = highest level first. */
		public List<Crop> cropRank = new ArrayList<>();
		/** Farming Guild contract crop to plant in the guild patch, or null. */
		public Crop contractCrop;
		/** Patches known to be diseased (bring plant cure / secateurs). */
		public Set<FarmPatch> diseased = EnumSet.noneOf(FarmPatch.class);
		/** Only plan the patches that are ready (or were just done this run). */
		public boolean onlyReady = false;
		/** Patches with something still growing: millis until ready, or -1 if unknown. */
		public Map<FarmPatch, Long> notReady = new java.util.EnumMap<>(FarmPatch.class);
		/** Patches you've just harvested/planted on this run, kept on the list as done. */
		public Set<FarmPatch> doneThisRun = EnumSet.noneOf(FarmPatch.class);
		/** What was just planted in each done patch (so compost / payment steps still show). */
		public Map<FarmPatch, Crop> plantedCrops = new java.util.EnumMap<>(FarmPatch.class);
		/** What's growing in each patch now (for the XP estimate of what you'll harvest). */
		public Map<FarmPatch, Crop> growingCrops = new java.util.EnumMap<>(FarmPatch.class);
		/** Average herbs per patch, for the XP estimate. */
		public double herbYield = HerbPrices.DEFAULT_YIELD;
		/** Levels, quests, spellbook, disabled teleports, spells/tabs, fairy chaining. */
		public Teleport.Context teleports = new Teleport.Context();
	}

	/** Coins the gardener charges to clear a fully grown tree so you can replant. */
	public static final int TREE_REMOVAL_COINS = 200;

	private static final String[] COMPOST_BEST_FIRST = {"Ultracompost", "Supercompost", "Compost"};

	/** Items you can wear instead of carrying, by equipment slot (first owned in a slot is worn). */
	private static final String[][] WEAR_SLOTS = {
		{"Magic secateurs", "Dramen staff", "Lunar staff"},
		{"Skills necklace", "Digsite pendant", "Pendant of ates", "Xeric's talisman"},
		{"Farming cape", "Ardougne cloak", "Hunter cape"},
		{"Explorer's ring"},
	};

	private RunPlanner()
	{
	}

	public static RunPlan plan(int farmingLevel, Set<FarmPatch> unlockedPatches,
		Map<String, Integer> owned, Options options)
	{
		RunPlan plan = new RunPlan();
		plan.farmingLevel = farmingLevel;
		plan.bankKnown = options.bankKnown;
		plan.unlocked.addAll(unlockedPatches);

		Teleport.Context ctx = options.teleports;
		ctx.owned = owned;
		for (Teleport t : Teleport.values())
		{
			plan.availability.put(t, t.check(ctx));
		}

		for (Crop crop : Crop.values())
		{
			if (crop.getLevel() <= farmingLevel)
			{
				plan.best.put(crop.getType(), crop);
			}
			else if (!plan.next.containsKey(crop.getType()))
			{
				plan.next.put(crop.getType(), crop);
			}
		}

		Set<PatchType> doing = EnumSet.noneOf(PatchType.class);
		for (PatchType t : options.runs)
		{
			if (plan.best.containsKey(t))
			{
				doing.add(t);
			}
			else
			{
				Crop first = plan.next.get(t);
				plan.warnings.add(t.getDisplayName() + " need level " + first.getLevel() + " Farming ("
					+ first.getDisplayName() + ").");
			}
		}

		Set<FarmPatch> included = EnumSet.noneOf(FarmPatch.class);
		for (FarmPatch patch : FarmPatch.values())
		{
			if (!doing.contains(patch.getType()))
			{
				continue;
			}
			if (!unlockedPatches.contains(patch))
			{
				plan.lockedPatches.add(patch);
				continue;
			}
			if (options.disabledPatches.contains(patch))
			{
				plan.skippedPatches.add(patch);
				continue;
			}
			included.add(patch);
		}

		if (options.onlyReady)
		{
			keepReadyPatches(plan, included, options);
		}

		// Decide what goes in each patch first: seeds go to the patches you use, then the rest.
		// A patch with nothing to plant and nothing of yours growing is left off the run.
		Map<FarmPatch, Crop> crops = new java.util.EnumMap<>(FarmPatch.class);
		for (PatchType t : doing)
		{
			allocateCrops(plan, t, included, owned, options, crops);
		}
		// Drop patches with nothing to plant, unless there's still something to do there:
		// harvesting herbs, checking a grown tree's health (XP), or curing a diseased tree.
		included.removeIf(p -> !crops.containsKey(p)
			&& (!options.usedPatches.contains(p)
				|| (p.getType().isTreeLike() && options.notReady.containsKey(p)
					&& !options.doneThisRun.contains(p) && !options.diseased.contains(p))));
		for (PatchType t : doing)
		{
			if (t.usesSaplings())
			{
				addSeedlingTips(plan, t, owned, options);
			}
		}

		List<RunPlan.RouteStep> picked = new ArrayList<>();
		for (FarmPatch patch : included)
		{
			picked.add(pickTeleport(patch, plan, ctx, included));
		}
		plan.route.addAll(orderRoute(picked, ctx));

		if (plan.route.isEmpty())
		{
			if (plan.warnings.isEmpty())
			{
				plan.warnings.add("No patches to visit.");
			}
			return plan;
		}

		if (!options.bankKnown)
		{
			plan.warnings.add("Open your bank once so the plugin can see what you own.");
		}

		for (RunPlan.RouteStep step : plan.route)
		{
			step.crop = crops.get(step.patch);
			step.done = options.doneThisRun.contains(step.patch);
			if (step.crop != null && step.patch.getType().hasGardenerPayment() && options.payGardeners
				&& step.crop.getPaymentItem() != null)
			{
				step.paymentItem = step.crop.getPaymentItem();
				step.paymentQuantity = step.crop.getPaymentQuantity();
			}
		}
		paymentWarnings(plan, owned);
		String bottomless = assignCompost(plan, owned, options);
		for (RunPlan.RouteStep s : plan.route)
		{
			// Only pay to clear a tree you're replacing; with no sapling, leave it standing.
			if (s.patch.getType().getClear() == PatchType.Clear.GARDENER && s.crop != null
				&& !options.doneThisRun.contains(s.patch))
			{
				s.coins = TREE_REMOVAL_COINS;
			}
		}

		List<RunPlan.Withdrawal> fixed = fixedItems(plan, owned, options, bottomless,
			doing.contains(PatchType.HERB) || doing.contains(PatchType.ALLOTMENT));
		plan.estimatedXp = estimateXp(plan, options);
		splitIntoTrips(plan, fixed, options);
		return plan;
	}

	private static boolean usable(FarmPatch.Route r, RunPlan plan, Teleport.Context ctx, Set<FarmPatch> included)
	{
		if (r.teleport == null)
		{
			// A walk only works if the patch it starts from is on this run.
			return r.anchor == null || included.contains(r.anchorPatch());
		}
		return plan.availability.get(r.teleport).available && !ctx.disabled.contains(r.teleport);
	}

	private static RunPlan.RouteStep pickTeleport(FarmPatch patch, RunPlan plan, Teleport.Context ctx,
		Set<FarmPatch> included)
	{
		List<FarmPatch.Route> usable = new ArrayList<>();
		for (FarmPatch.Route r : patch.getRoutes())
		{
			if (usable(r, plan, ctx, included))
			{
				usable.add(r);
			}
		}

		// Spells / tabs toggles. When both are allowed and a spell works here, skip the tab.
		boolean spellHere = false;
		List<FarmPatch.Route> filtered = new ArrayList<>();
		for (FarmPatch.Route r : usable)
		{
			Teleport.Kind k = r.teleport == null ? null : r.teleport.getKind();
			if ((k == Teleport.Kind.SPELL && !ctx.useSpells) || (k == Teleport.Kind.TABLET && !ctx.useTabs))
			{
				continue;
			}
			spellHere |= k == Teleport.Kind.SPELL;
			filtered.add(r);
		}
		usable = new ArrayList<>();
		for (FarmPatch.Route r : filtered)
		{
			if (!(spellHere && r.teleport != null && r.teleport.getKind() == Teleport.Kind.TABLET))
			{
				usable.add(r);
			}
		}

		FarmPatch.Route chosen = null;

		// A walk from the patch you just did always wins (you're already there).
		for (FarmPatch.Route r : usable)
		{
			if (r.teleport == null && r.anchor != null)
			{
				chosen = r;
				break;
			}
		}

		if (chosen == null && ctx.chainFairyRings)
		{
			FarmPatch.Route fairy = null;
			boolean beaten = false;
			for (FarmPatch.Route r : usable)
			{
				if (r.beatsFairy)
				{
					beaten = true;
					break;
				}
				if (r.teleport != null && r.teleport.getKind() == Teleport.Kind.FAIRY_RING)
				{
					fairy = r;
					break;
				}
			}
			if (!beaten && fairy != null)
			{
				chosen = fairy;
			}
		}

		if (chosen == null && !usable.isEmpty())
		{
			chosen = usable.get(0);
		}

		if (chosen == null)
		{
			FarmPatch.Route best = patch.getRoutes().get(0);
			return new RunPlan.RouteStep(patch, null, "No teleport available (best: " + best.describe() + ")", null, false);
		}
		String item = null;
		if (chosen.teleport != null && (chosen.teleport.getKind() == Teleport.Kind.ITEM
			|| chosen.teleport.getKind() == Teleport.Kind.TABLET))
		{
			item = plan.availability.get(chosen.teleport).ownedItem;
		}
		RunPlan.RouteStep step = new RunPlan.RouteStep(patch, chosen.teleport, chosen.describe(), item, true);
		step.anchor = chosen.teleport == null ? chosen.anchorPatch() : null;
		return step;
	}

	private static boolean isFairy(RunPlan.RouteStep s)
	{
		return s.teleport != null && s.teleport.getKind() == Teleport.Kind.FAIRY_RING;
	}

	/**
	 * Keeps the base order, but pulls every fairy-ring stop together into one chain that starts
	 * right after a patch with a fairy ring nearby (e.g. Ardougne cloak, then walk to BLR).
	 * Walk stops stay glued to the stop before them. Fairy directions say which code to dial.
	 */
	static List<RunPlan.RouteStep> orderRoute(List<RunPlan.RouteStep> steps, Teleport.Context ctx)
	{
		// Group into blocks: a stop plus any walks that follow it.
		List<List<RunPlan.RouteStep>> blocks = new ArrayList<>();
		for (RunPlan.RouteStep s : steps)
		{
			List<RunPlan.RouteStep> home = s.anchor == null ? null : blockWith(blocks, s.anchor);
			if (home != null)
			{
				home.add(s);
			}
			else
			{
				List<RunPlan.RouteStep> b = new ArrayList<>();
				b.add(s);
				blocks.add(b);
			}
		}

		List<List<RunPlan.RouteStep>> fairy = new ArrayList<>();
		List<List<RunPlan.RouteStep>> other = new ArrayList<>();
		for (List<RunPlan.RouteStep> b : blocks)
		{
			(isFairy(b.get(0)) ? fairy : other).add(b);
		}

		List<List<RunPlan.RouteStep>> ordered = new ArrayList<>();
		String startRing = null;
		if (fairy.isEmpty())
		{
			ordered.addAll(other);
		}
		else
		{
			// Start the chain from the patch whose ring is the shortest walk away.
			int starter = -1;
			int bestRank = Integer.MAX_VALUE;
			for (int i = 0; i < other.size(); i++)
			{
				RunPlan.RouteStep head = other.get(i).get(0);
				String ring = head.patch.getNearbyRing();
				if (head.hasTeleport && ring != null && ringWalkRank(ring) < bestRank)
				{
					starter = i;
					bestRank = ringWalkRank(ring);
				}
			}
			if (starter < 0)
			{
				ordered.addAll(fairy);
				ordered.addAll(other);
			}
			else
			{
				ordered.addAll(other.subList(0, starter + 1));
				ordered.addAll(fairy);
				ordered.addAll(other.subList(starter + 1, other.size()));
				startRing = other.get(starter).get(0).patch.getNearbyRing();
			}
		}

		// Flatten and rewrite fairy directions based on where you're coming from.
		List<RunPlan.RouteStep> out = new ArrayList<>();
		RunPlan.RouteStep prev = null;
		for (List<RunPlan.RouteStep> b : ordered)
		{
			for (RunPlan.RouteStep s : b)
			{
				RunPlan.RouteStep step = s;
				if (isFairy(s))
				{
					String code = s.teleport.getFairyCode();
					String rest = s.teleportLabel.substring(s.teleport.getLabel().length());
					String from;
					if (prev != null && isFairy(prev))
					{
						from = "Back to the ring, dial " + code;
					}
					else if (prev != null && startRing != null && prev.patch.getNearbyRing() != null)
					{
						from = "Walk " + direction(prev.patch, FairyRings.tile(prev.patch.getNearbyRing()))
							+ "to fairy ring " + prev.patch.getNearbyRing() + ", dial " + code;
					}
					else
					{
						from = "From any fairy ring, dial " + code;
					}
					step = new RunPlan.RouteStep(s.patch, s.teleport, from + rest, null, true);
					step.crop = s.crop;
				}
				out.add(step);
				prev = step;
			}
		}
		return out;
	}

	/** Lower = the ring is closer to its patch (ALQ is right by the Morytania patch; BLR is a walk). */
	private static int ringWalkRank(String ring)
	{
		switch (ring)
		{
			case "ALQ":
				return 1;
			case "AKR":
				return 2;
			case "CIR":
				return 3;
			case "AJP":
				return 4;
			default:
				return 9;
		}
	}

	private static List<RunPlan.RouteStep> blockWith(List<List<RunPlan.RouteStep>> blocks, FarmPatch patch)
	{
		for (List<RunPlan.RouteStep> b : blocks)
		{
			for (RunPlan.RouteStep s : b)
			{
				if (s.patch == patch)
				{
					return b;
				}
			}
		}
		return null;
	}

	/**
	 * Hands out the best seeds/saplings you own to this type's patches: patches you already use
	 * first, then the rest in route order. Patches left without one simply aren't in the map.
	 */
	private static void allocateCrops(RunPlan plan, PatchType type, Set<FarmPatch> included,
		Map<String, Integer> owned, Options options, Map<FarmPatch, Crop> out)
	{
		List<Crop> plantable = new ArrayList<>();
		for (Crop crop : Crop.values())
		{
			if (crop.getType() == type && crop.getLevel() <= plan.farmingLevel
				&& !options.disabledCrops.contains(crop))
			{
				plantable.add(crop);
			}
		}
		if (plantable.isEmpty())
		{
			plan.warnings.add("No " + type.getDisplayName().toLowerCase()
				+ " ticked to plant. Pick some in the run's section.");
			return;
		}
		List<Crop> preference = new ArrayList<>(plantable);
		java.util.Collections.reverse(preference);
		if (!options.cropRank.isEmpty())
		{
			// Stable sort: ranked crops first in rank order, the rest stay highest level first.
			preference.sort(java.util.Comparator.comparingInt(c ->
			{
				int i = options.cropRank.indexOf(c);
				return i < 0 ? Integer.MAX_VALUE : i;
			}));
		}
		List<Crop> queue = new ArrayList<>();
		for (Crop crop : preference)
		{
			int have = owned.getOrDefault(crop.getSeedName(), 0) / crop.getSeedsPerPatch();
			for (int n = 0; n < have; n++)
			{
				queue.add(crop);
			}
		}
		// Patches you've just planted on this run don't need another seed.
		List<FarmPatch> order = new ArrayList<>();
		for (FarmPatch p : included)
		{
			if (p.getType() == type && options.usedPatches.contains(p) && !options.doneThisRun.contains(p))
			{
				order.add(p);
			}
		}
		for (FarmPatch p : included)
		{
			if (p.getType() == type && !options.usedPatches.contains(p) && !options.doneThisRun.contains(p))
			{
				order.add(p);
			}
		}
		for (FarmPatch p : included)
		{
			if (p.getType() == type && options.doneThisRun.contains(p) && options.plantedCrops.containsKey(p))
			{
				out.put(p, options.plantedCrops.get(p));
			}
		}
		Crop contract = options.contractCrop;
		if (contract != null && contract.getType() == type)
		{
			FarmPatch guild = type == PatchType.HERB ? FarmPatch.FARMING_GUILD_HERB
				: type == PatchType.TREE ? FarmPatch.FARMING_GUILD_TREE
				: type == PatchType.FRUIT_TREE ? FarmPatch.FARMING_GUILD_FRUIT
				: type == PatchType.ALLOTMENT ? FarmPatch.GUILD_ALLOTMENT_A
				: type == PatchType.BUSH ? FarmPatch.GUILD_BUSH
				: type == PatchType.CACTUS ? FarmPatch.GUILD_CACTUS
				: type == PatchType.CELASTRUS ? FarmPatch.GUILD_CELASTRUS
				: type == PatchType.REDWOOD ? FarmPatch.GUILD_REDWOOD : null;
			if (guild != null && order.contains(guild))
			{
				if (owned.getOrDefault(contract.getSeedName(), 0) >= contract.getSeedsPerPatch() && contract.getLevel() <= plan.farmingLevel)
				{
					out.put(guild, contract);
					queue.remove(contract);
					order.remove(guild);
				}
				else
				{
					plan.warnings.add("Farming contract: bring " + aOrAn(contract.getSeedName()) + " "
						+ contract.getSeedName().toLowerCase() + " for the Farming Guild patch.");
				}
			}
		}
		if (type == PatchType.SPIRIT_TREE)
		{
			// A spirit tree is kept once planted (grown, it's a teleport), so patches with one in
			// aren't replanted, and each counts towards how many you may have planted at once,
			// which depends on your Farming level (OSRS Wiki).
			int allowed = spiritTreeLimit(plan.farmingLevel);
			int occupied = 0;
			for (FarmPatch p : FarmPatch.values())
			{
				if (p.getType() == PatchType.SPIRIT_TREE && options.growingCrops.containsKey(p))
				{
					occupied++;
				}
			}
			order.removeIf(options.growingCrops::containsKey);
			int cap = Math.max(0, allowed - occupied);
			if (order.size() > cap)
			{
				plan.warnings.add("Spirit trees: at Farming " + plan.farmingLevel + " you can have " + allowed
					+ " planted at once" + (occupied > 0 ? " (" + occupied + " already planted)" : "")
					+ ", so " + (cap == 0 ? "none are" : "only " + cap + " " + (cap == 1 ? "is" : "are")) + " planted this run.");
				order = new ArrayList<>(order.subList(0, cap));
			}
		}
		int next = 0;
		int unplanted = 0;
		for (FarmPatch p : order)
		{
			if (next < queue.size())
			{
				out.put(p, queue.get(next++));
			}
			else
			{
				unplanted++;
			}
		}
		if (unplanted > 0 && !order.isEmpty())
		{
			Crop best = plantable.get(plantable.size() - 1);
			String what = type.seedWord();
			String patchName = type.patchName();
			String rest = !type.isTreeLike() ? "the others are only harvested"
				: "the others are just checked for health if grown (and left standing), or left off";
			plan.warnings.add((order.size() == unplanted ? "No " + what + " for your " + patchName + " patches: "
				+ (!type.isTreeLike() ? "patches are only harvested" : "grown ones are just checked for health and left standing")
				: "Only enough " + what + " for " + (order.size() - unplanted) + " of " + order.size()
				+ " " + patchName + " patches: " + rest) + ". Best you can plant: " + best.getSeedName() + ".");
		}
	}

	/** Spirit trees you may have planted at once: 1 at 83, 2 at 88, 3 at 93, 4 at 96, any at 99. */
	static int spiritTreeLimit(int farmingLevel)
	{
		if (farmingLevel >= 99)
		{
			return Integer.MAX_VALUE / 2;
		}
		return farmingLevel >= 96 ? 4 : farmingLevel >= 93 ? 3 : farmingLevel >= 88 ? 2 : farmingLevel >= 83 ? 1 : 0;
	}

	/** Remind you to pot and water tree seeds, so you have saplings for later runs. */
	/**
	 * Leaves growing patches off the run when at least one patch is ready, so one ready herb
	 * doesn't turn into a full run. When nothing is ready the full run is shown for planning.
	 */
	static void keepReadyPatches(RunPlan plan, Set<FarmPatch> included, Options options)
	{
		List<FarmPatch> waiting = new ArrayList<>();
		boolean anyReady = false;
		for (FarmPatch p : included)
		{
			if (options.doneThisRun.contains(p) || !options.notReady.containsKey(p))
			{
				anyReady = true;
			}
			else
			{
				waiting.add(p);
			}
		}
		if (waiting.isEmpty())
		{
			return;
		}
		FarmPatch soonest = null;
		long soonestMs = Long.MAX_VALUE;
		for (FarmPatch p : waiting)
		{
			long ms = options.notReady.get(p);
			if (ms >= 0 && ms < soonestMs)
			{
				soonestMs = ms;
				soonest = p;
			}
		}
		String next = soonest == null ? "" : " Next up: " + soonest.getDisplayName() + " in "
			+ roughTime(soonestMs) + ".";
		if (anyReady)
		{
			included.removeAll(waiting);
			plan.tips.add(waiting.size() + (waiting.size() == 1 ? " patch is" : " patches are")
				+ " still growing, so only the ready ones are on this run." + next);
		}
		else
		{
			plan.tips.add("Nothing is ready yet." + next + " This is the full run for when they are.");
		}
	}

	/** "south " / "north-west " from a patch to a tile (with a rough distance when it's a walk), or "". */
	static String direction(FarmPatch from, int[] to)
	{
		if (to == null)
		{
			return "";
		}
		int dx = to[0] - from.getX();
		int dy = to[1] - from.getY();
		int d = Math.max(Math.abs(dx), Math.abs(dy));
		if (d < 4)
		{
			return "";
		}
		String ns = Math.abs(dy) * 2 < Math.abs(dx) ? "" : dy > 0 ? "north" : "south";
		String ew = Math.abs(dx) * 2 < Math.abs(dy) ? "" : dx > 0 ? "east" : "west";
		String dir = ns.isEmpty() ? ew : ew.isEmpty() ? ns : ns + "-" + ew;
		return dir + (d >= 15 ? " (about " + (Math.round(d / 5.0) * 5) + " tiles) " : " ");
	}

	/** About how much XP the run gives: what you collect from grown crops, planting, and compost. */
	static double estimateXp(RunPlan plan, Options options)
	{
		double xp = 0;
		for (RunPlan.RouteStep s : plan.route)
		{
			if (s.done)
			{
				continue;
			}
			Crop growing = options.growingCrops.get(s.patch);
			if (growing != null && !options.notReady.containsKey(s.patch))
			{
				xp += FarmingXp.grown(growing, options.herbYield);
			}
			if (s.crop != null)
			{
				xp += FarmingXp.plant(s.crop) + FarmingXp.compost(s.compost);
			}
		}
		return xp;
	}

	private static String aOrAn(String word)
	{
		return "AEIOUaeiou".indexOf(word.charAt(0)) >= 0 ? "an" : "a";
	}

	/** "about 30 min" / "about 2h 10m" - rounded up, so the tip doesn't need to tick. */
	private static String roughTime(long ms)
	{
		long min = Math.max(1, (ms + 59_999) / 60_000);
		return "about " + (min < 60 ? min + " min" : (min / 60) + "h " + (min % 60) + "m");
	}

	static void addSeedlingTips(RunPlan plan, PatchType type, Map<String, Integer> owned, Options options)
	{
		for (Crop c : Crop.values())
		{
			if (c.getType() != type || c.getLevel() > plan.farmingLevel || options.disabledCrops.contains(c))
			{
				continue;
			}
			String name = c.getDisplayName().toLowerCase();
			int seeds = owned.getOrDefault(c.getTreeSeedName(), 0);
			int seedlings = owned.getOrDefault(c.getSeedlingName(), 0);
			int watered = owned.getOrDefault(c.getWateredSeedlingName(), 0);
			if (seeds > 0)
			{
				plan.tips.add("You have " + seeds + " " + c.getTreeSeedName().toLowerCase() + (seeds > 1 ? "s" : "")
					+ ": plant them in plant pots filled with soil (use a gardening trowel) and water them."
					+ " They grow into " + name + " saplings for later runs.");
			}
			if (seedlings > 0)
			{
				plan.tips.add("Water your " + seedlings + " " + name + " seedling" + (seedlings > 1 ? "s" : "")
					+ " with a watering can so they grow into saplings.");
			}
			if (watered > 0)
			{
				plan.tips.add(watered + " watered " + name + " seedling" + (watered > 1 ? "s are" : " is")
					+ " growing into saplings. Keep them in your bank or inventory.");
			}
		}
	}

	private static void paymentWarnings(RunPlan plan, Map<String, Integer> owned)
	{
		Map<String, Integer> need = new LinkedHashMap<>();
		for (RunPlan.RouteStep s : plan.route)
		{
			if (s.paymentItem != null && !s.done)
			{
				need.merge(s.paymentItem, s.paymentQuantity, Integer::sum);
				for (String[] extra : s.crop.getExtraPayments())
				{
					need.merge(extra[0], Integer.parseInt(extra[1]), Integer::sum);
				}
			}
		}
		need.forEach((item, qty) ->
		{
			int have = owned.getOrDefault(item, 0);
			if (have < qty)
			{
				plan.warnings.add("Short " + (qty - have) + " " + item + " to pay the gardeners.");
			}
		});
	}

	/** Returns the bottomless bucket's name if used, else assigns compost per stop best-first. */
	private static String assignCompost(RunPlan plan, Map<String, Integer> owned, Options options)
	{
		if (!options.useCompost)
		{
			return null;
		}
		for (String name : owned.keySet())
		{
			if (name.startsWith("Bottomless compost bucket") && owned.get(name) > 0)
			{
				for (RunPlan.RouteStep s : plan.route)
				{
					if (s.crop != null)
					{
						s.compost = name;
					}
				}
				return name;
			}
		}
		Map<String, Integer> left = new LinkedHashMap<>();
		for (String c : COMPOST_BEST_FIRST)
		{
			left.put(c, owned.getOrDefault(c, 0));
		}
		int missing = 0;
		for (RunPlan.RouteStep s : plan.route)
		{
			if (s.crop == null)
			{
				continue; // nothing being planted here
			}
			if (s.done)
			{
				// Just planted: point at the best compost you're carrying, without reserving it.
				for (String c : COMPOST_BEST_FIRST)
				{
					if (owned.getOrDefault(c, 0) > 0)
					{
						s.compost = c;
						break;
					}
				}
				continue;
			}
			for (String c : COMPOST_BEST_FIRST)
			{
				if (left.get(c) > 0)
				{
					s.compost = c;
					left.merge(c, -1, Integer::sum);
					break;
				}
			}
			if (s.compost == null)
			{
				missing++;
			}
		}
		if (missing > 0)
		{
			plan.warnings.add("Short " + missing + " compost.");
		}
		return null;
	}

	/** Tools, teleports, runes, staff: carried for the whole run. */
	private static List<RunPlan.Withdrawal> fixedItems(RunPlan plan, Map<String, Integer> owned, Options options,
		String bottomless, boolean herbs)
	{
		List<RunPlan.Withdrawal> out = new ArrayList<>();
		if (herbs)
		{
			requireTool(plan, out, owned, "Seed dibber");
		}
		requireTool(plan, out, owned, "Spade");
		if (options.bringRake)
		{
			requireTool(plan, out, owned, "Rake");
		}
		if (bottomless != null)
		{
			out.add(new RunPlan.Withdrawal(bottomless, 1, "make sure it's filled"));
		}
		if (herbs && owned.getOrDefault("Magic secateurs", 0) > 0)
		{
			out.add(new RunPlan.Withdrawal("Magic secateurs", 1, "+10% herb yield, wield it"));
		}

		// Diseased patches: plant cure for herbs, secateurs to prune trees.
		int sickHerbs = 0;
		boolean sickTree = false;
		for (RunPlan.RouteStep step : plan.route)
		{
			if (options.diseased.contains(step.patch))
			{
				if (!step.patch.getType().isTreeLike())
				{
					sickHerbs++;
				}
				else
				{
					sickTree = true;
				}
			}
		}
		if (sickHerbs > 0)
		{
			out.add(new RunPlan.Withdrawal("Plant cure", sickHerbs, "for the diseased herb patch"));
			if (owned.getOrDefault("Plant cure", 0) < sickHerbs)
			{
				plan.warnings.add("Buy " + sickHerbs + " plant cure (Farming shops or the GE) for your diseased herbs.");
			}
		}
		if (sickTree && owned.getOrDefault("Magic secateurs", 0) == 0)
		{
			requireTool(plan, out, owned, "Secateurs");
		}

		// Teleport items and tablets
		Map<String, Integer> uses = new LinkedHashMap<>();
		Map<String, String> firstPatch = new LinkedHashMap<>();
		Map<String, Integer> runes = new LinkedHashMap<>();
		boolean fairy = false;
		boolean unknownRunes = false;
		for (RunPlan.RouteStep step : plan.route)
		{
			if (step.teleportItem != null)
			{
				uses.merge(step.teleportItem, 1, Integer::sum);
				firstPatch.putIfAbsent(step.teleportItem, step.patch.getDisplayName());
			}
			if (step.teleport == null)
			{
				continue;
			}
			if (step.teleport.getKind() == Teleport.Kind.SPELL)
			{
				unknownRunes |= step.teleport.getRunes().isEmpty();
				step.teleport.getRunes().forEach((rune, qty) -> runes.merge(rune, qty, Integer::sum));
			}
			else if (step.teleport.getKind() == Teleport.Kind.FAIRY_RING)
			{
				fairy = true;
			}
			else if (step.teleport == Teleport.SPIRIT_TREE)
			{
				// Getting to the spirit tree by the Grand Exchange: Varrock Teleport (spell or tab).
				Teleport.Context ctx = options.teleports;
				if (ctx.useSpells && ctx.standardSpellbook && ctx.magicLevel >= 25)
				{
					Teleport.VARROCK_SPELL.getRunes().forEach((rune, qty) -> runes.merge(rune, qty, Integer::sum));
				}
				else if (owned.getOrDefault("Varrock teleport", 0) > 0)
				{
					uses.merge("Varrock teleport", 1, Integer::sum);
					firstPatch.putIfAbsent("Varrock teleport", step.patch.getDisplayName());
				}
			}
		}
		for (Map.Entry<String, Integer> e : uses.entrySet())
		{
			String name = e.getKey();
			int qty = name.toLowerCase().endsWith(" teleport") ? e.getValue() : 1;
			out.add(new RunPlan.Withdrawal(name, qty, firstPatch.get(name)));
		}
		for (Map.Entry<String, Integer> e : runes.entrySet())
		{
			out.add(new RunPlan.Withdrawal(e.getKey(), e.getValue(), "spell runes"));
			int have = owned.getOrDefault(e.getKey(), 0);
			if (have < e.getValue())
			{
				plan.warnings.add("Short " + (e.getValue() - have) + " " + e.getKey()
					+ " (fine if a staff or rune pouch covers it).");
			}
		}
		if (unknownRunes)
		{
			plan.warnings.add("Check the runes for Kourend/Civitas teleports in your spellbook.");
		}
		if (fairy && !options.teleports.staffless)
		{
			String staff = Teleport.staffName(owned);
			if (staff != null)
			{
				out.add(new RunPlan.Withdrawal(staff, 1, "wield it for fairy rings"));
			}
		}
		return out;
	}

	private static void requireTool(RunPlan plan, List<RunPlan.Withdrawal> out, Map<String, Integer> owned, String tool)
	{
		out.add(new RunPlan.Withdrawal(tool, 1, ""));
		if (owned.getOrDefault(tool, 0) <= 0)
		{
			plan.warnings.add("You don't seem to own a " + tool + " (unless it's in a tool leprechaun store).");
		}
	}

	/** Slots the fixed items take, counting one wearable per equipment slot as worn. */
	static int fixedSlots(List<RunPlan.Withdrawal> fixed)
	{
		int slots = 0;
		boolean[] worn = new boolean[WEAR_SLOTS.length];
		outer:
		for (RunPlan.Withdrawal w : fixed)
		{
			for (int i = 0; i < WEAR_SLOTS.length; i++)
			{
				for (String prefix : WEAR_SLOTS[i])
				{
					if (w.itemName.startsWith(prefix) && !worn[i])
					{
						worn[i] = true;
						continue outer;
					}
				}
			}
			slots++;
		}
		return slots;
	}

	/** Slots one leg's supplies take: saplings and unnoted compost one each; seeds, payments, coins stack. */
	static int legSlots(List<RunPlan.RouteStep> leg)
	{
		Set<String> stackTypes = new LinkedHashSet<>();
		int slots = 0;
		for (RunPlan.RouteStep s : leg)
		{
			if (s.crop != null && !s.done)
			{
				if (s.patch.getType().seedsStack())
				{
					stackTypes.add(s.crop.getSeedName());
				}
				else
				{
					slots++;
				}
			}
			if (s.compost != null && !s.compost.startsWith("Bottomless"))
			{
				slots++;
			}
			if (s.paymentItem != null)
			{
				stackTypes.add(s.paymentItem + " (noted)");
				for (String[] extra : s.crop.getExtraPayments())
				{
					stackTypes.add(extra[0] + " (noted)");
				}
			}
			if (s.coins > 0)
			{
				stackTypes.add("Coins");
			}
		}
		return slots + stackTypes.size();
	}

	/**
	 * Splits the route into legs that each fit in one inventory, adding a bank stop before
	 * each new leg. The first leg's supplies plus the fixed items are what you take at the start.
	 */
	static void splitIntoTrips(RunPlan plan, List<RunPlan.Withdrawal> fixed, Options options)
	{
		int fixedSlots = fixedSlots(fixed);
		List<List<RunPlan.RouteStep>> legs = new ArrayList<>();
		List<Integer> legStart = new ArrayList<>();
		List<RunPlan.RouteStep> leg = new ArrayList<>();
		for (int i = 0; i < plan.route.size(); i++)
		{
			RunPlan.RouteStep s = plan.route.get(i);
			leg.add(s);
			if (leg.size() > 1 && fixedSlots + legSlots(leg) > options.inventorySlots)
			{
				leg.remove(leg.size() - 1);
				legs.add(leg);
				legStart.add(i - leg.size());
				leg = new ArrayList<>();
				leg.add(s);
			}
		}
		legs.add(leg);
		legStart.add(plan.route.size() - leg.size());

		plan.withdrawals.addAll(supplies(legs.get(0)));
		plan.withdrawals.addAll(fixed);
		plan.slotsNeeded = fixedSlots + legSlots(legs.get(0));

		for (int l = 1; l < legs.size(); l++)
		{
			int before = legStart.get(l);
			String bank = null;
			for (int i = before - 1; i >= 0 && bank == null; i--)
			{
				bank = plan.route.get(i).patch.getBank();
			}
			RunPlan.BankStop stop = new RunPlan.BankStop(before, bank == null ? "the nearest bank" : bank);
			stop.withdrawals.addAll(supplies(legs.get(l)));
			plan.bankStops.add(stop);
		}
	}

	private static List<RunPlan.Withdrawal> supplies(List<RunPlan.RouteStep> leg)
	{
		Map<String, Integer> seeds = new LinkedHashMap<>();
		Map<String, Integer> compost = new LinkedHashMap<>();
		Map<String, Integer> pay = new LinkedHashMap<>();
		Map<String, String> notes = new LinkedHashMap<>();
		int coins = 0;
		for (RunPlan.RouteStep s : leg)
		{
			if (s.done)
			{
				continue; // planted already: nothing more to bring for it
			}
			if (s.crop != null)
			{
				seeds.merge(s.crop.getSeedName(), s.crop.getSeedsPerPatch(), Integer::sum);
				notes.put(s.crop.getSeedName(), "level " + s.crop.getLevel());
			}
			if (s.compost != null && !s.compost.startsWith("Bottomless"))
			{
				compost.merge(s.compost, 1, Integer::sum);
			}
			if (s.paymentItem != null)
			{
				pay.merge(s.paymentItem, s.paymentQuantity, Integer::sum);
				for (String[] extra : s.crop.getExtraPayments())
				{
					pay.merge(extra[0], Integer.parseInt(extra[1]), Integer::sum);
				}
			}
			coins += s.coins;
		}
		List<RunPlan.Withdrawal> out = new ArrayList<>();
		seeds.forEach((k, v) -> out.add(new RunPlan.Withdrawal(k, v, notes.get(k))));
		compost.forEach((k, v) -> out.add(new RunPlan.Withdrawal(k, v, "")));
		pay.forEach((k, v) ->
		{
			// Same item used two ways (e.g. compost for potatoes): one line with the total.
			for (int i = 0; i < out.size(); i++)
			{
				RunPlan.Withdrawal w = out.get(i);
				if (w.itemName.equals(k))
				{
					out.set(i, new RunPlan.Withdrawal(k, w.quantity + v, "for the patches and to pay the gardeners"));
					return;
				}
			}
			out.add(new RunPlan.Withdrawal(k, v, "gardener payment, noted is fine"));
		});
		if (coins > 0)
		{
			out.add(new RunPlan.Withdrawal("Coins", coins, "gardener clears grown trees, "
				+ TREE_REMOVAL_COINS + " each"));
		}
		return out;
	}
}

package com.herbrunhelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/** A small on-screen box: which runs are ready, diseased patches and your farming contract. */
class RunReadyOverlay extends OverlayPanel
{
	static final class Line
	{
		final String left;
		final String right;
		final Color color;

		Line(String left, String right, Color color)
		{
			this.left = left;
			this.right = right;
			this.color = color;
		}
	}

	private final HerbRunPlugin plugin;

	@Inject
	RunReadyOverlay(HerbRunPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<Line> lines = plugin.getReadyLines();
		if (!plugin.showReadyOverlay() || lines.isEmpty())
		{
			return null;
		}
		panelComponent.getChildren().add(TitleComponent.builder().text("Farm runs").color(new Color(255, 200, 60)).build());
		for (Line l : lines)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(l.left).right(l.right).rightColor(l.color).build());
		}
		return super.render(graphics);
	}
}

package com.herbrunhelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.io.InputStream;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.util.LinkBrowser;

/**
 * A row of buttons to ToadFx's channels, all the same light grey. Each opens in your web browser.
 * The marks are simple drawings, not the official logos; a channel's own icon can be dropped in
 * as resources/com/herbrunhelper/social/&lt;name&gt;.png (e.g. tiktok.png) and is used instead.
 */
final class SocialLinks
{
	private static final int SIZE = 22;
	private static final Color BUTTON = new Color(215, 215, 215);
	private static final Color MARK = new Color(40, 40, 40);

	enum Social
	{
		YOUTUBE("YouTube", "youtube", "https://www.youtube.com/@toadfxx"),
		TWITCH("Twitch", "twitch", "https://www.twitch.tv/toadfxx"),
		KICK("Kick", "kick", "https://kick.com/toadfx"),
		TIKTOK("TikTok", "tiktok", "https://www.tiktok.com/@toadfx");

		final String name;
		final String file;
		final String url;

		Social(String name, String file, String url)
		{
			this.name = name;
			this.file = file;
			this.url = url;
		}
	}

	private SocialLinks()
	{
	}

	static JPanel row()
	{
		JPanel row = new JPanel(new FlowLayout(FlowLayout.CENTER, 6, 0));
		row.setOpaque(false);
		for (Social s : Social.values())
		{
			JLabel b = new JLabel(new ImageIcon(icon(s)));
			b.setToolTipText("ToadFx on " + s.name);
			b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
			b.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseClicked(MouseEvent e)
				{
					LinkBrowser.browse(s.url);
				}
			});
			row.add(b);
		}
		return row;
	}

	/** The channel's own icon if one was added to the plugin, else a grey button with a simple mark. */
	static BufferedImage icon(Social s)
	{
		BufferedImage own = resource(s);
		BufferedImage img = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		g.setColor(BUTTON);
		g.fill(new RoundRectangle2D.Float(0, 0, SIZE, SIZE, 7, 7));
		if (own != null)
		{
			g.drawImage(own.getScaledInstance(SIZE - 6, SIZE - 6, Image.SCALE_SMOOTH), 3, 3, null);
			g.dispose();
			return img;
		}
		g.setColor(MARK);
		switch (s)
		{
			case YOUTUBE:
			{
				Path2D p = new Path2D.Float();
				p.moveTo(8, 6);
				p.lineTo(16, 11);
				p.lineTo(8, 16);
				p.closePath();
				g.fill(p);
				break;
			}
			case TWITCH:
			{
				// A chat bubble with two bars.
				g.setStroke(new BasicStroke(1.8f));
				Path2D p = new Path2D.Float();
				p.moveTo(5, 4.5);
				p.lineTo(17, 4.5);
				p.lineTo(17, 13);
				p.lineTo(13, 16);
				p.lineTo(9.5, 16);
				p.lineTo(7, 18.5);
				p.lineTo(7, 16);
				p.lineTo(5, 16);
				p.closePath();
				g.draw(p);
				g.fillRect(9, 8, 2, 4);
				g.fillRect(13, 8, 2, 4);
				break;
			}
			case KICK:
			{
				g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 14));
				int w = g.getFontMetrics().stringWidth("K");
				g.drawString("K", (SIZE - w) / 2f, 16);
				break;
			}
			default:
			{
				// A music note.
				g.fill(new Ellipse2D.Float(5.5f, 12.5f, 6, 5));
				g.fillRect(10, 4, 2, 11);
				Path2D flag = new Path2D.Float();
				flag.moveTo(12, 4);
				flag.curveTo(13.5, 6.5, 16.5, 6.5, 17, 9);
				flag.lineTo(17, 10.5);
				flag.curveTo(15.5, 8.8, 13.5, 8.5, 12, 7.5);
				flag.closePath();
				g.fill(flag);
				break;
			}
		}
		g.dispose();
		return img;
	}

	private static BufferedImage resource(Social s)
	{
		try (InputStream in = SocialLinks.class.getResourceAsStream("social/" + s.file + ".png"))
		{
			return in == null ? null : ImageIO.read(in);
		}
		catch (Exception e)
		{
			return null;
		}
	}
}

package com.herbrunhelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Outlines the teleport spell for your next stop in the spellbook (e.g. Falador Teleport). */
class SpellHighlightOverlay extends Overlay
{
	/** The spellbook interface. */
	private static final int SPELLBOOK_GROUP = 218;
	private static final int MAX_CHILD = 250;

	private final Client client;
	private final HerbRunPlugin plugin;
	private final HerbRunConfig config;

	@Inject
	SpellHighlightOverlay(Client client, HerbRunPlugin plugin, HerbRunConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String spell = plugin.getSpellToHighlight();
		if (spell == null)
		{
			return null;
		}
		Widget w = findSpell(spell);
		if (w == null)
		{
			return null;
		}
		Rectangle bounds = w.getBounds();
		if (bounds == null || bounds.width <= 0)
		{
			return null;
		}
		Color c = config.stepColor();
		graphics.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 70));
		graphics.fill(bounds);
		graphics.setColor(c);
		graphics.setStroke(new BasicStroke(2));
		graphics.draw(bounds);
		return null;
	}

	/** The spell's icon in the open spellbook, found by its name (it moves between game updates). */
	private Widget findSpell(String spell)
	{
		for (int child = 0; child < MAX_CHILD; child++)
		{
			Widget w = client.getWidget(SPELLBOOK_GROUP, child);
			if (w == null || w.isHidden())
			{
				continue;
			}
			String name = w.getName();
			if (name != null && name.replaceAll("<[^>]*>", "").trim().equalsIgnoreCase(spell))
			{
				return w;
			}
		}
		return null;
	}
}

package com.herbrunhelper;

/**
 * Which inventory item the stop you're at needs next, so it can be highlighted.
 * Order at a patch: rake weeds / dig up dead or stump / coins for the gardener to clear a
 * grown tree, then the seed or sapling, then compost, then the gardener's protection payment.
 * Pure Java so it can be tested.
 */
public final class StepItems
{
	/** What's happened at one stop since you arrived. */
	public static final class Progress
	{
		public final long plantedAt;
		public boolean composted;
		public boolean paid;
		/** How many of the compost / payment you carried when you planted (to spot them being used). */
		public final int compostBaseline;
		public final int paymentBaseline;

		public Progress(long plantedAt, int compostBaseline, int paymentBaseline)
		{
			this.plantedAt = plantedAt;
			this.compostBaseline = compostBaseline;
			this.paymentBaseline = paymentBaseline;
		}
	}

	/** The item to highlight and a short label for it. */
	public static final class Next
	{
		public final String item;
		public final String action;

		Next(String item, String action)
		{
			this.item = item;
			this.action = action;
		}
	}

	/** How long after planting we keep pointing at compost/payment for that stop. */
	public static final long PROGRESS_WINDOW_MILLIS = 15 * 60_000L;

	private StepItems()
	{
	}

	/** Null when nothing in the inventory is needed right now (e.g. harvesting, or the stop is finished). */
	public static Next next(RunPlan.RouteStep step, PatchTimers.Planting planting, PatchTimers.Status status,
		Progress progress, long now)
	{
		return next(step, planting, status, progress, now, false);
	}

	/**
	 * @param checkHealthDue the game says this grown tree's health hasn't been checked yet: do
	 *     that first (it's where the XP is), then pay the gardener to clear it
	 */
	public static Next next(RunPlan.RouteStep step, PatchTimers.Planting planting, PatchTimers.Status status,
		Progress progress, long now, boolean checkHealthDue)
	{
		return next(step, planting, status, progress, now, checkHealthDue, null);
	}

	/**
	 * True if a gardener's line says they're now looking after the patch (you've paid), or already
	 * were. From the OSRS Wiki gardener transcripts.
	 */
	public static boolean saysProtected(String dialogue)
	{
		if (dialogue == null)
		{
			return false;
		}
		String t = dialogue.replaceAll("<[^>]*>", " ").toLowerCase();
		return t.contains("leave it with me")
			|| t.contains("make sure that patch grows")
			|| t.contains("make sure it grows")
			|| t.contains("already looking after");
	}

	/** What the game shows on a grown plant, so the steps go in the right order. */
	public enum Grown
	{
		/** Berries, spines or bark still on it: pick them before digging it up. */
		PRODUCE,
		/** Harvested celastrus: chop it down (then dig up the stump). */
		CHOP,
		/** Nothing left to take: clear it. */
		CLEAR
	}

	/**
	 * @param grown what's on the grown plant right now (from the game), or null if not known
	 */
	public static Next next(RunPlan.RouteStep step, PatchTimers.Planting planting, PatchTimers.Status status,
		Progress progress, long now, boolean checkHealthDue, Grown grown)
	{
		PatchType type = step.patch.getType();
		boolean planted = progress != null && now - progress.plantedAt < PROGRESS_WINDOW_MILLIS;

		if (planted)
		{
			if (step.compost != null && !progress.composted)
			{
				return new Next(step.compost, "Add compost");
			}
			if (type.hasGardenerPayment() && step.paymentItem != null && !progress.paid)
			{
				return new Next(step.paymentItem, "Pay the gardener");
			}
			return null;
		}

		if (status == PatchTimers.Status.WEEDS)
		{
			return new Next("Rake", "Rake the weeds");
		}
		if (status == PatchTimers.Status.DEAD || status == PatchTimers.Status.STUMP)
		{
			return new Next("Spade", "Dig it up");
		}
		if (checkHealthDue && type.isTreeLike())
		{
			return new Next(null, "Check the " + StopWork.plantName(type, planting != null ? planting.crop : null) + "'s health");
		}
		boolean ready = grown != null || (planting != null && planting.isReady(now));
		if (ready && !type.isTreeLike())
		{
			return null; // harvest by clicking the patch
		}
		if (ready && type.isTreeLike())
		{
			// Pick the berries / spines / bark first (no item needed), then clear it.
			if (grown == Grown.PRODUCE)
			{
				String pick = StopWork.pickLine(type, planting != null ? planting.crop : null);
				if (pick != null)
				{
					return new Next(null, pick);
				}
			}
			// Nothing to replant: just check health, don't clear it.
			if (step.crop == null)
			{
				return null;
			}
			if (grown == Grown.CHOP)
			{
				return new Next(null, "Chop it down");
			}
			return type.getClear() == PatchType.Clear.GARDENER ? new Next("Coins", "Pay the gardener to clear it")
				: new Next("Spade", "Dig it up");
		}
		if (step.crop != null)
		{
			return new Next(step.crop.getSeedName(), "Plant");
		}
		return null;
	}
}

package com.herbrunhelper;

import java.util.ArrayList;
import java.util.List;

/** The to-do list for one stop, from what the plugin knows about the patch. Pure Java. */
public final class StopWork
{
	private StopWork()
	{
	}

	public static List<String> describe(RunPlan.RouteStep step, PatchTimers.Planting planting,
		PatchTimers.Status status, long now)
	{
		List<String> out = new ArrayList<>();
		PatchType type = step.patch.getType();
		boolean ready = planting != null && planting.isReady(now);
		String seed = step.crop == null ? null : step.crop.getSeedName().toLowerCase();

		if (!type.isTreeLike())
		{
			if (ready)
			{
				out.add("Harvest the " + planting.crop.getDisplayName().toLowerCase() + " (note them at the leprechaun)");
			}
			else if (status == PatchTimers.Status.DISEASED)
			{
				out.add("Diseased: cure with plant cure, or dig it up");
			}
			else if (status == PatchTimers.Status.DEAD)
			{
				out.add("Dead: dig it up with your spade");
			}
			else if (status == PatchTimers.Status.WEEDS)
			{
				out.add("Rake the weeds");
			}
			else if (planting == null && status == null)
			{
				out.add("Harvest if anything's grown");
			}
		}
		else
		{
			String tree = plantName(type, planting != null ? planting.crop : null);
			if (ready)
			{
				out.add("Check the " + tree + "'s health");
				String pick = pickLine(type, planting.crop);
				if (pick != null)
				{
					out.add(pick);
				}
				if (seed != null)
				{
					out.add(clearLine(type));
				}
				else
				{
					out.add("Leave it standing: nothing to replant (it won't die)");
				}
			}
			else if (status == PatchTimers.Status.STUMP)
			{
				out.add("Dig up the stump with your spade");
			}
			else if (status == PatchTimers.Status.DISEASED)
			{
				out.add("Diseased: prune it with secateurs");
			}
			else if (status == PatchTimers.Status.DEAD)
			{
				out.add("Dead: dig it up with your spade");
			}
			else if (status == PatchTimers.Status.WEEDS)
			{
				out.add("Rake the weeds");
			}
			else if (planting == null && status == null)
			{
				out.add(seed != null ? "If a grown " + tree + " is there: check its health, then "
					+ clearLine(type).substring(0, 1).toLowerCase() + clearLine(type).substring(1)
					: "If a grown " + tree + " is there: check its health");
			}
		}

		if (seed != null)
		{
			if (step.crop.getSeedsPerPatch() > 1)
			{
				out.add("Plant " + step.crop.getSeedsPerPatch() + " " + seed + "s");
			}
			else
			{
				String article = type != PatchType.HERB ? "the " : "aeiou".indexOf(seed.charAt(0)) >= 0 ? "an " : "a ";
				out.add("Plant " + article + seed);
			}
		}
		else if (!type.isTreeLike())
		{
			out.add("No seed left to plant here");
		}
		if (step.compost != null && seed != null)
		{
			out.add(step.compost.startsWith("Bottomless") ? "Use your bottomless compost bucket" : "Add " + step.compost.toLowerCase());
		}
		if (step.paymentItem != null && seed != null)
		{
			StringBuilder pay = new StringBuilder("Pay the gardener " + step.paymentQuantity + " x " + step.paymentItem);
			String[][] extra = step.crop.getExtraPayments();
			for (int i = 0; i < extra.length; i++)
			{
				pay.append(i == extra.length - 1 ? " and " : ", ").append(extra[i][1]).append(" x ").append(extra[i][0]);
			}
			out.add(pay + " to protect it");
		}
		return out;
	}

	/** "maple tree", "redberry bush", "potato cactus", "spirit tree"... */
	static String plantName(PatchType type, Crop crop)
	{
		String name = crop == null ? null : crop.getDisplayName().toLowerCase();
		switch (type)
		{
			case BUSH:
				return name == null ? "bush" : name + " bush";
			case CACTUS:
				return name == null ? "cactus" : name;
			case SPIRIT_TREE:
				return "spirit tree";
			default:
				return name == null ? "tree" : name + " tree";
		}
	}

	/** What there is to take from a grown plant before clearing it, if anything. */
	static String pickLine(PatchType type, Crop crop)
	{
		switch (type)
		{
			case FRUIT_TREE:
				return "Pick the fruit if you want it (note at the leprechaun)";
			case BUSH:
				return "Pick the berries (note at the leprechaun)";
			case CACTUS:
				return crop == Crop.POTATO_CACTUS ? "Pick the potato cacti" : "Pick the cactus spines";
			case CALQUAT:
				return "Pick the calquat fruit if you want it";
			case CELASTRUS:
				return "Harvest the bark (it doesn't grow back)";
			default:
				return null;
		}
	}

	/** How to get rid of the grown plant so you can replant. */
	static String clearLine(PatchType type)
	{
		switch (type)
		{
			case BUSH:
				return "Dig up the bush with your spade";
			case CACTUS:
				return "Dig up the cactus with your spade";
			case SPIRIT_TREE:
				return "Dig it up with your spade (it can't be cut down)";
			case CELASTRUS:
			case REDWOOD:
				return "Chop it down, then dig up the stump with your spade";
			default:
				return "Pay the gardener " + RunPlanner.TREE_REMOVAL_COINS + " coins to chop it down";
		}
	}

	/**
	 * Is this to-do line the step the plugin is pointing you at right now (the action shown at
	 * the top of the panel and highlighted in game)?
	 */
	public static boolean isCurrent(String line, String action)
	{
		if (line == null || action == null)
		{
			return false;
		}
		String l = line.toLowerCase();
		String a = action.toLowerCase();
		if (a.startsWith("rake"))
		{
			return l.startsWith("rake");
		}
		if (a.startsWith("dig"))
		{
			return l.contains("dig");
		}
		if (a.startsWith("check the"))
		{
			return l.startsWith("check the") || l.startsWith("if a grown");
		}
		if (a.startsWith("pay the gardener to clear"))
		{
			return l.contains("chop it down") || l.contains("to clear it");
		}
		if (a.startsWith("pay the gardener"))
		{
			return l.contains("to protect it");
		}
		if (a.startsWith("pick") || a.startsWith("harvest"))
		{
			return l.startsWith(a.split(" ")[0]);
		}
		if (a.startsWith("chop it down"))
		{
			return l.startsWith("chop it down");
		}
		if (a.startsWith("plant"))
		{
			return l.startsWith("plant");
		}
		if (a.startsWith("add compost"))
		{
			return l.startsWith("add ") || l.startsWith("use your bottomless");
		}
		return false;
	}
}

